// 1. Try to get a JWT Token using the plugin endpoint
const getJwtToken = async (baseUrl: string, username: string, password: string): Promise<string | null> => {
    try {
        const response = await fetch(`${baseUrl}/wp-json/jwt-auth/v1/token`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ username, password })
        });
        const data = await response.json();
        return data.token || null;
    } catch (e) {
        console.warn("JWT Token retrieval failed:", e);
        return null;
    }
};

export const publishToWordPress = async (config: PublishingConfig, title: string, content: string, imageBase64?: string, tags?: string, publishDate?: Date) => {
    if (!config.wpUrl || !config.wpUsername || !config.wpAppPassword) throw new Error("WordPress не настроен");

    const baseUrl = config.wpUrl.replace(/\/$/, '');
    // Safe Base64 for Russian Usernames
    const basicAuth = safeBtoa(`${config.wpUsername}:${config.wpAppPassword}`);

    // Helper to handle requests with Aggressive Fallback
    const performWpRequest = async (endpoint: string, method: string, body?: any, isFileUpload = false) => {
        const url = `${baseUrl}/wp-json/wp/v2/${endpoint}`;

        // Strategy 1: Standard Basic Auth
        const standardHeaders: any = { 'Authorization': `Basic ${basicAuth}` };
        if (!isFileUpload) standardHeaders['Content-Type'] = 'application/json';

        const standardOptions: RequestInit = {
            method,
            headers: standardHeaders,
            body: body
        };

        let res;
        try {
            res = await fetchWithTimeout(url, standardOptions, 30000);
        } catch (e: any) {
            throw e; 
        }

        // Strategy 2: JWT Plugin Fallback (If Basic Auth fails)
        if (res.status === 401 || res.status === 403) {
            console.warn(`Basic Auth failed. Trying JWT Plugin Auth...`);

            const jwtToken = await getJwtToken(baseUrl, config.wpUsername, config.wpAppPassword);

            if (jwtToken) {
                 const jwtHeaders: any = { 'Authorization': `Bearer ${jwtToken}` };
                 if (!isFileUpload) jwtHeaders['Content-Type'] = 'application/json';

                 res = await fetchWithTimeout(url, {
                    method,
                    headers: jwtHeaders,
                    body
                 }, 30000);
            } else {
                 // Strategy 3: Aggressive URL Params (Last resort)
                 console.warn(`JWT failed. Trying URL Params...`);
                 const urlObj = new URL(url);
                 urlObj.searchParams.append('api_key', config.wpAppPassword); 
                 urlObj.searchParams.append('key', config.wpAppPassword);     
                 urlObj.searchParams.append('token', config.wpAppPassword);   
                 urlObj.searchParams.append('username', config.wpUsername); 

                 const fallbackHeaders: any = {};
                 if (!isFileUpload) fallbackHeaders['Content-Type'] = 'application/json';

                 res = await fetchWithTimeout(urlObj.toString(), {
                    method,
                    headers: fallbackHeaders, 
                    body
                 }, 30000);
            }
        }

        return handleWpResponse(res, endpoint);
    };

    const handleWpResponse = async (res: Response, context: string) => {
        if (!res.ok) {
            let errorMsg = res.statusText;
            try {
                const json = await res.json();
                errorMsg = json.message || json.code || errorMsg;
                if (res.status === 401) {
                     // Detailed error for user
                     throw new Error(`ОШИБКА 401. Сервер отклонил пароль. 1) Проверьте что плагин JWT Authentication включен. 2) Проверьте Application Password в настройках. 3) Проверьте .htaccess`);
                }
            } catch (e: any) {
                 if (e.message.includes('ОШИБКА')) throw e;
            }
            throw new Error(`WP ${context} Error (${res.status}): ${errorMsg}`);
        }
        return res.json();
    };

    let featuredMediaId = 0;

    // 1. Upload Image
    if (imageBase64) {
        try {
            const blob = await base64ToBlob(imageBase64);
            const formData = new FormData();
            formData.append('file', blob, 'image.jpg');

            const uploadData = await performWpRequest('media', 'POST', formData, true);
            featuredMediaId = uploadData.id;
        } catch (e) {
            console.warn("WP Image Upload Failed", e);
        }
    }

    // 2. Create Post
    const status = publishDate ? 'future' : 'draft';

    const postBody: any = {
        title: title,
        content: content,
        status: status,
        featured_media: featuredMediaId > 0 ? featuredMediaId : undefined,
    };

    if (publishDate) {
        postBody.date = publishDate.toISOString();
    }

    return await performWpRequest('posts', 'POST', JSON.stringify(postBody));
};

