// 1. Try to get a JWT Token using the plugin endpoint
const getJwtToken = async (baseUrl: string, username: string, password: string): Promise<string | null> => {
    try {
        // We pass creds in BODY, not Header, to avoid 401 stripping issues during login
        const response = await fetch(`${baseUrl}/wp-json/jwt-auth/v1/token`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ username, password })
        });
        const data = await response.json();
        return data.token || null;
    } catch (e) {
        console.warn("JWT Token retrieval failed:", e);
        return null;
    }
};

export const publishToWordPress = async (config: PublishingConfig, title: string, content: string, imageBase64?: string, tags?: string, publishDate?: Date) => {
    if (!config.wpUrl || !config.wpUsername || !config.wpAppPassword) throw new Error("WordPress не настроен");

    const baseUrl = config.wpUrl.replace(/\/$/, '');
    const basicAuth = safeBtoa(`${config.wpUsername}:${config.wpAppPassword}`);

    const performWpRequest = async (endpoint: string, method: string, body?: any, isFileUpload = false) => {
        const url = `${baseUrl}/wp-json/wp/v2/${endpoint}`;

        // 1. Try Basic Auth (Standard)
        // If this fails immediately with 401, headers are likely stripped.
        try {
            const standardHeaders: any = { 'Authorization': `Basic ${basicAuth}` };
            if (!isFileUpload) standardHeaders['Content-Type'] = 'application/json';

            const res = await fetchWithTimeout(url, {
                method,
                headers: standardHeaders,
                body
            }, 10000); // Fast timeout for first try

            if (res.ok) return res.json();
            if (res.status !== 401 && res.status !== 403) {
                 return handleWpResponse(res, endpoint); // Return normal errors
            }
        } catch (e) { console.log("Basic Auth Attempt failed, trying JWT..."); }

        // 2. Fallback: JWT Auth
        console.warn(`Basic Auth blocked (401). Trying JWT Plugin flow...`);
        const jwtToken = await getJwtToken(baseUrl, config.wpUsername, config.wpAppPassword);

        if (!jwtToken) {
            throw new Error(`ОШИБКА 401. Сервер не принимает пароль. 1) Проверьте логин/пароль. 2) Если у вас Application Password, попробуйте обычный пароль от админки для JWT плагина.`);
        }

        // 2a. Try JWT in Header
        try {
            const jwtHeaders: any = { 'Authorization': `Bearer ${jwtToken}` };
            if (!isFileUpload) jwtHeaders['Content-Type'] = 'application/json';

            const res = await fetchWithTimeout(url, {
                method,
                headers: jwtHeaders,
                body
            }, 15000);

            if (res.ok) return res.json();
        } catch (e) { console.log("JWT Header Attempt failed..."); }

        // 2b. Try JWT in URL (Aggressive fallback for servers stripping headers)
        console.warn(`JWT Header blocked. Trying URL Token...`);
        const urlObj = new URL(url);
        urlObj.searchParams.append('token', jwtToken); // Standard for jwt-auth plugin

        const fallbackHeaders: any = {};
        if (!isFileUpload) fallbackHeaders['Content-Type'] = 'application/json';

        const finalRes = await fetchWithTimeout(urlObj.toString(), {
            method,
            headers: fallbackHeaders, 
            body
        }, 30000);

        return handleWpResponse(finalRes, endpoint);
