// 1. Try to get a JWT Token using the plugin endpoint
const getJwtToken = async (baseUrl: string, username: string, password: string): Promise<string | null> => {
    // FIX: Force HTTPS if needed, otherwise redirects will strip the POST body
    let cleanUrl = baseUrl;
    if (cleanUrl.startsWith('http://') && !cleanUrl.includes('localhost')) {
        cleanUrl = cleanUrl.replace('http://', 'https://');
    }

    try {
        console.log(`Attempting JWT Auth at: ${cleanUrl}/wp-json/jwt-auth/v1/token`);

        const response = await fetch(`${cleanUrl}/wp-json/jwt-auth/v1/token`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ username, password })
        });

        const contentType = response.headers.get("content-type");

        // Handle HTML Errors (403/404/500)
        if (contentType && contentType.indexOf("application/json") === -1) {
             const text = await response.text();
             console.error("JWT Endpoint returned non-JSON:", text.substring(0, 300));

             if (response.status === 403) {
                 if (text.includes("incorrect") || text.includes("password")) {
                     throw new Error(`ОШИБКА 403: Неверный логин или пароль! Пожалуйста, проверьте настройки.`);
                 }
                 if (text.includes("Wordfence") || text.includes("security") || text.includes("denied")) {
                     throw new Error(`ОШИБКА 403: Доступ заблокирован плагином безопасности (например, Wordfence). Отключите его или добавьте REST API в исключения.`);
                 }
                 throw new Error(`ОШИБКА 403: Доступ запрещен сервером. Проверьте логин/пароль.`);
             }

             throw new Error(`Сервер вернул ошибку HTML (${response.status}) вместо JSON. Возможно, плагин JWT не активирован или адрес сайта неверен.`);
        }

        const data = await response.json();

        if (!response.ok) {
             console.warn("JWT Auth failed:", data);
             // Specific error for wrong password in JSON format
             if (data.code === '[jwt_auth] incorrect_password' || (data.message && data.message.includes('incorrect'))) {
                 throw new Error("Неверный пароль администратора!");
             }
             return null;
        }

        return data.token || null;
    } catch (e: any) {
        console.warn("JWT Token retrieval failed:", e.message);
        // Re-throw specific errors so they bubble up to the UI
        if (e.message.includes("ОШИБКА") || e.message.includes("Неверный")) {
            throw e; 
        }
        return null;
    }
};

export const publishToWordPress = async (config: PublishingConfig, title: string, content: string, imageBase64?: string, tags?: string, publishDate?: Date) => {
    if (!config.wpUrl || !config.wpUsername || !config.wpAppPassword) throw new Error("WordPress не настроен");

    let baseUrl = config.wpUrl.replace(/\/$/, '');
    if (baseUrl.startsWith('http://') && !baseUrl.includes('localhost')) {
         baseUrl = baseUrl.replace('http://', 'https://');
    }

    const basicAuth = safeBtoa(`${config.wpUsername}:${config.wpAppPassword}`);

    const performWpRequest = async (endpoint: string, method: string, body?: any, isFileUpload = false) => {
        const url = `${baseUrl}/wp-json/wp/v2/${endpoint}`;

        // 1. Try Basic Auth (Standard)
        try {
            const standardHeaders: any = { 'Authorization': `Basic ${basicAuth}` };
            if (!isFileUpload) standardHeaders['Content-Type'] = 'application/json';

            const res = await fetchWithTimeout(url, {
                method,
                headers: standardHeaders,
                body
            }, 10000); 

            if (res.ok) return res.json();
            if (res.status !== 401 && res.status !== 403) {
                 return handleWpResponse(res, endpoint); 
            }
        } catch (e) { console.log("Basic Auth Attempt failed, trying JWT..."); }

        // 2. Fallback: JWT Auth
        console.warn(`Basic Auth blocked. Trying JWT Plugin flow...`);
        let jwtToken;
        try {
            jwtToken = await getJwtToken(baseUrl, config.wpUsername, config.wpAppPassword);
        } catch (e: any) {
            // Stop immediately if we know it's a password error
            throw e;
        }

        if (!jwtToken) {
            throw new Error(`ОШИБКА 401. Не удалось авторизоваться. 1) Проверьте логин/пароль. 2) Убедитесь, что код добавлен в wp-config.php. 3) Отключите плагины безопасности.`);
        }

        // 2a. Try JWT in Header
        try {
            const jwtHeaders: any = { 'Authorization': `Bearer ${jwtToken}` };
            if (!isFileUpload) jwtHeaders['Content-Type'] = 'application/json';

            const res = await fetchWithTimeout(url, {
                method,
                headers: jwtHeaders,
                body
            }, 15000);

            if (res.ok) return res.json();
        } catch (e) { console.log("JWT Header Attempt failed..."); }

        // 2b. Try JWT in URL (Aggressive fallback)
        console.warn(`JWT Header blocked. Trying URL Token...`);
        const urlObj = new URL(url);
        urlObj.searchParams.append('token', jwtToken); 

        const fallbackHeaders: any = {};
        if (!isFileUpload) fallbackHeaders['Content-Type'] = 'application/json';

        const finalRes = await fetchWithTimeout(urlObj.toString(), {
            method,
            headers: fallbackHeaders, 
            body
        }, 30000);

        return handleWpResponse(finalRes, endpoint);
    };

    const handleWpResponse = async (res: Response, context: string) => {
        if (!res.ok) {
            let errorMsg = res.statusText;
            try {
                const json = await res.json();
                errorMsg = json.message || json.code || errorMsg;
            } catch (e) {}
            throw new Error(`WP ${context} Error (${res.status}): ${errorMsg}`);
        }
        return res.json();
    };

    let featuredMediaId = 0;

    // Upload Image
    if (imageBase64) {
        try {
            const blob = await base64ToBlob(imageBase64);
            const formData = new FormData();
            formData.append('file', blob, 'image.jpg');
            const uploadData = await performWpRequest('media', 'POST', formData, true);
            featuredMediaId = uploadData.id;
        } catch (e) {
            console.warn("WP Image Upload Failed (likely auth)", e);
        }
    }

    // Create Post
    const status = publishDate ? 'future' : 'draft';
    const postBody: any = {
        title: title,
        content: content,
        status: status,
        featured_media: featuredMediaId > 0 ? featuredMediaId : undefined,
    };
    if (publishDate) postBody.date = publishDate.toISOString();

    return await performWpRequest('posts', 'POST', JSON.stringify(postBody));
};

