        const headers: any = { 
            'Authorization': `Basic ${basicAuth}`
        };
        if (!isFileUpload) {
            headers['Content-Type'] = 'application/json';
        }

        const res = await fetchWithTimeout(url, {
            method,
            headers,
            body
        }, 15000);

        // ERROR HANDLING
        if (!res.ok) {
            if (res.status === 401 || res.status === 403) {
                // If we get here using an App Password, it's 99% a Server Header issue
                throw new Error(
                    `ОШИБКА АВТОРИЗАЦИИ (${res.status}). \n` +
