            let errorMsg = res.statusText;
            try {
                const json = await res.json();
                errorMsg = json.message || json.code || errorMsg;
            } catch (e) {}
            throw new Error(`WordPress Error (${res.status}): ${errorMsg}`);
        }

        return res.json();
