import { PublishingConfig } from "../types";

// Helper: Fetch with Timeout (prevents hanging)
const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 30000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
        const response = await fetch(url, {
            ...options,
            signal: controller.signal
        });
        clearTimeout(id);
        return response;
    } catch (error: any) {
        clearTimeout(id);
        if (error.name === 'AbortError') {
            throw new Error(`Превышено время ожидания (${timeout / 1000}с). Сервер не отвечает.`);
        }
        throw error;
    }
};

// Helper to convert Base64 to Blob
const base64ToBlob = async (base64: string): Promise<Blob> => {
  const res = await fetch(base64);
  return await res.blob();
};

// Helper for UTF-8 safe Basic Auth encoding
const safeBtoa = (str: string) => {
    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g,
        (match, p1) => String.fromCharCode(parseInt(p1, 16))
    ));
};

// --- TELEGRAM ---
export const publishToTelegram = async (config: PublishingConfig, text: string, imageBase64?: string, publishDate?: Date) => {
  if (!config.telegramBotToken || !config.telegramChatId) throw new Error("Telegram не настроен");

  const formData = new FormData();
  formData.append('chat_id', config.telegramChatId);
  formData.append('parse_mode', 'HTML'); 

  if (publishDate) {
      const unixTime = Math.floor(publishDate.getTime() / 1000);
      formData.append('schedule_date', unixTime.toString());
  }

  const endpoint = imageBase64 ? 'sendPhoto' : 'sendMessage';

  if (imageBase64) {
    const blob = await base64ToBlob(imageBase64);
    formData.append('photo', blob, 'image.jpg');
    formData.append('caption', text.substring(0, 1024)); 
  } else {
    formData.append('text', text);
  }

  const response = await fetchWithTimeout(`https://api.telegram.org/bot${config.telegramBotToken}/${endpoint}`, {
    method: 'POST',
    body: formData
  }, 15000);

  const data = await response.json();
  if (!data.ok) throw new Error(`Telegram Error: ${data.description}`);
  return data;
};

// --- VKONTAKTE ---
export const publishToVK = async (config: PublishingConfig, text: string, imageBase64?: string, publishDate?: Date) => {
    if (!config.vkAccessToken || !config.vkOwnerId) throw new Error("ВКонтакте не настроен");
    const ownerId = config.vkOwnerId.startsWith('-') ? config.vkOwnerId : `-${config.vkOwnerId}`; 
    let attachments = '';

    if (imageBase64) {
        try {
            const serverRes = await jsonpRequest(`https://api.vk.com/method/photos.getWallUploadServer?group_id=${ownerId.replace('-', '')}&access_token=${config.vkAccessToken}&v=5.131`);
            const uploadUrl = serverRes.response.upload_url;
            const blob = await base64ToBlob(imageBase64);
            const formData = new FormData();
            formData.append('photo', blob, 'image.jpg');

            const uploadResponse = await fetchWithTimeout(uploadUrl, { method: 'POST', body: formData }, 20000);
            const uploadResult = await uploadResponse.json();

            const saveRes = await jsonpRequest(`https://api.vk.com/method/photos.saveWallPhoto?group_id=${ownerId.replace('-', '')}&photo=${uploadResult.photo}&server=${uploadResult.server}&hash=${uploadResult.hash}&access_token=${config.vkAccessToken}&v=5.131`);
            if (saveRes.response?.length > 0) {
                attachments = `photo${saveRes.response[0].owner_id}_${saveRes.response[0].id}`;
            }
        } catch (e) { console.warn("VK Photo error", e); }
    }

    const params: any = { access_token: config.vkAccessToken, owner_id: ownerId, message: text, from_group: '1', v: '5.131' };
    if (attachments) params.attachments = attachments;
    if (publishDate) params.publish_date = Math.floor(publishDate.getTime() / 1000).toString();

    return await jsonpRequest(`https://api.vk.com/method/wall.post?${new URLSearchParams(params).toString()}`);
};

async function jsonpRequest(url: string): Promise<any> {
    const callbackName = 'vk_callback_' + Math.round(Math.random() * 1000000);
    const script = document.createElement('script');
    return new Promise((resolve, reject) => {
        // @ts-ignore
        window[callbackName] = (data: any) => {
            document.body.removeChild(script);
            // @ts-ignore
            delete window[callbackName];
            resolve(data);
        };
        script.src = `${url}&callback=${callbackName}`;
        script.onerror = () => reject(new Error("VK API JSONP failed"));
        document.body.appendChild(script);
    });
}

// --- WORDPRESS ---

export const publishToWordPress = async (
    config: PublishingConfig, 
    title: string, 
    content: string, 
    imageBase64?: string, 
    tags?: string, 
    publishDate?: Date,
    metaDescription?: string
) => {
    if (!config.wpUrl || !config.wpUsername || !config.wpAppPassword) throw new Error("WordPress не настроен");

    let baseUrl = config.wpUrl.replace(/\/$/, '');
    if (baseUrl.startsWith('http://') && !baseUrl.includes('localhost')) {
         baseUrl = baseUrl.replace('http://', 'https://');
    }

    const basicAuth = safeBtoa(`${config.wpUsername}:${config.wpAppPassword}`);

    const performWpRequest = async (endpoint: string, method: string, body?: any, isFileUpload = false) => {
        const url = `${baseUrl}/wp-json/wp/v2/${endpoint}`;
        const headers: any = { 'Authorization': `Basic ${basicAuth}` };
        if (!isFileUpload) headers['Content-Type'] = 'application/json';

        const res = await fetchWithTimeout(url, { method, headers, body }, 25000);
        if (!res.ok) {
            const json = await res.json().catch(() => ({}));
            throw new Error(`WP Error: ${json.message || res.statusText}`);
        }
        return res.json();
    };

    let featuredMediaId = 0;

    // 1. Загрузка фото
    if (imageBase64) {
        try {
            const blob = await base64ToBlob(imageBase64);
            const formData = new FormData();
            // WP REST API ожидает файл в поле 'file'
            formData.append('file', blob, `article-${Date.now()}.jpg`);
            formData.append('title', title);
            formData.append('alt_text', title);

            const uploadData = await performWpRequest('media', 'POST', formData, true);
            featuredMediaId = uploadData.id;
        } catch (e: any) {
            console.warn("Media Upload Failed:", e.message);
        }
    }

    // 2. Сборка контента + SEO блок в конце
    let finalContent = content;
    finalContent += `\n\n---\n\n`;
    finalContent += `<!-- SEO INFO BLOCK -->\n`;
    if (metaDescription) {
        finalContent += `**Description (мета-описание):** ${metaDescription}\n\n`;
    }
    if (tags) {
        const formattedTags = tags.split(',').map(t => `#${t.trim().replace(/\s+/g, '')}`).join(' ');
        finalContent += `**Hashtags (теги):** ${formattedTags}\n`;
    }
    finalContent += `<!-- END SEO INFO BLOCK -->`;

    // 3. Публикация записи
    const status = publishDate ? 'future' : 'draft';
    const postBody: any = {
        title: title,
        content: finalContent,
        status: status,
        excerpt: metaDescription || '', // Системное поле описания
        featured_media: featuredMediaId > 0 ? featuredMediaId : undefined,
    };

    if (publishDate) postBody.date = publishDate.toISOString();

    return await performWpRequest('posts', 'POST', JSON.stringify(postBody));
};

