export const replaceNewsItems = async (currentNews: NewsItem[], excludeIds: string[]): Promise<NewsItem[]> => {
    const model = "gemini-2.5-flash";
    const keptTitles = currentNews.filter(n => !excludeIds.includes(n.id)).map(n => n.title);
    const prompt = `Замени ${excludeIds.length} новостей. Исключи темы: ${keptTitles.join(', ')}. Верни JSON массив NewsItem.`;

    const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: { tools: [{ googleSearch: {} }] }
    });
    const newItems: any[] = cleanAndParseJSON(response.text || "[]");
    return newItems.map((item: any, index: number) => ({
        ...item,
        id: `news-replaced-${index}-${Date.now()}`
    }));
};

export const generateCreativeContent = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const models = ["gemini-3-pro-preview", "gemini-2.5-flash"];
  let lastError;

  const prompt = `
    ТЫ — ВЕДУЩИЙ КОЛУМНИСТ "ПЕРВОГО ТУРИСТИЧЕСКОГО".
    Стиль: интеллектуальная ирония, без "Я/Мы".

    ЗАДАЧА:
    1. Статья для сайта (Markdown).
    2. Пост для Telegram.
    3. Пост для VK.

    ПРАВИЛА ДЛЯ ХЕШТЕГОВ:
    - Поле hashtags: СЛОВА ЧЕРЕЗ ЗАПЯТУЮ, БЕЗ СИМВОЛА #. Только текст. (Пример: туризм, авиация, отдых)
    - Внутри текстов соцсетей: С символом #.

    ИЛЛЮСТРАЦИИ: Создай 3 РАЗНЫХ промпта для фотореализма.

    JSON:
    {
      "siteArticle": { "headline": "...", "content": "Markdown...", "hashtags": "слово1, слово2, слово3" },
      "telegramPost": { "content": "..." },
      "vkPost": { "content": "..." },
      "imagePrompts": ["P1", "P2", "P3"],
      "metaDescription": "..."
    }
  `;

  for (const model of models) {
    try {
        const response = await ai.models.generateContent({
          model,
          contents: `Новость: "${newsItem.title}". ${prompt}`,
          config: { tools: [{ googleSearch: {} }] }
        });
        const json = cleanAndParseJSON(response.text || "{}");

        const enforcedPrompts = (json.imagePrompts || []).slice(0, 3).map((p: string) => {
            let clean = p.replace(/--ar\s+\d+:\d+/g, '').trim();
            return `Hyper-realistic raw photography, shot on Sony A7R IV, 85mm, f/1.8, cinematic lighting, 8k, ${clean} --ar 16:9 --no illustration, drawing, cgi`;
        });

        // Ensure we always have 3 prompts
        while(enforcedPrompts.length < 3) enforcedPrompts.push(`Hyper-realistic travel photography, cinematic view of ${newsItem.location || 'travel destination'} --ar 16:9`);

        return {
          newsId: newsItem.id,
          ...json,
          imagePrompts: enforcedPrompts,
          generatedImages: []
        };
    } catch (error: any) {
        lastError = error;
    }
  }
  throw new Error(`Ошибка: ${lastError?.message}`);
};

export const generateImage = async (prompt: string, aspectRatio: string = "16:9"): Promise<string | null> => {
    const cleanPrompt = prompt.replace(/--ar\s+\d+:\d+/g, '').trim();
    const finalPrompt = `raw photo, hyperrealistic, 8k, ${cleanPrompt} --no cgi, text, watermark`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-image-preview",
            contents: { parts: [{ text: finalPrompt }] },
            config: { imageConfig: { aspectRatio, imageSize: "1K" } }
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData?.data) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } catch (e) {
        const resFlash = await ai.models.generateContent({
            model: "gemini-2.5-flash-image",
            contents: { parts: [{ text: finalPrompt }] },
            config: { imageConfig: { aspectRatio } }
        });
        const p = resFlash.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (p?.inlineData?.data) return `data:${p.inlineData.mimeType};base64,${p.inlineData.data}`;
    }
    return null;
}

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
