  return images;
};

import { PublishingConfig } from "../types";

const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 30000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
        const response = await fetch(url, { ...options, signal: controller.signal });
        clearTimeout(id);
        return response;
    } catch (error: any) {
        clearTimeout(id);
        throw error;
    }
};

const base64ToBlob = async (base64: string): Promise<Blob> => {
  const res = await fetch(base64);
  return await res.blob();
};

const safeBtoa = (str: string) => {
    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g,
        (match, p1) => String.fromCharCode(parseInt(p1, 16))
    ));
};

export const publishToTelegram = async (config: PublishingConfig, text: string, imageBase64?: string, publishDate?: Date) => {
  if (!config.telegramBotToken || !config.telegramChatId) throw new Error("Telegram не настроен");
  const formData = new FormData();
  formData.append('chat_id', config.telegramChatId);
  formData.append('parse_mode', 'HTML'); 
  if (publishDate) formData.append('schedule_date', Math.floor(publishDate.getTime() / 1000).toString());

  const endpoint = imageBase64 ? 'sendPhoto' : 'sendMessage';
  if (imageBase64) {
    const blob = await base64ToBlob(imageBase64);
    formData.append('photo', blob, 'image.jpg');
    formData.append('caption', text.substring(0, 1024)); 
  } else {
    formData.append('text', text);
  }

  const response = await fetchWithTimeout(`https://api.telegram.org/bot${config.telegramBotToken}/${endpoint}`, { method: 'POST', body: formData });
  const data = await response.json();
  if (!data.ok) throw new Error(`Telegram Error: ${data.description}`);
  return data;
};

export const publishToVK = async (config: PublishingConfig, text: string, imageBase64?: string, publishDate?: Date) => {
    if (!config.vkAccessToken || !config.vkOwnerId) throw new Error("ВКонтакте не настроен");
    const ownerId = config.vkOwnerId.startsWith('-') ? config.vkOwnerId : `-${config.vkOwnerId}`; 
    let attachments = '';

    if (imageBase64) {
        try {
            const serverRes = await jsonpRequest(`https://api.vk.com/method/photos.getWallUploadServer?group_id=${ownerId.replace('-', '')}&access_token=${config.vkAccessToken}&v=5.131`);
            const blob = await base64ToBlob(imageBase64);
            const formData = new FormData();
            formData.append('photo', blob, 'image.jpg');
            const uploadRes = await (await fetch(serverRes.response.upload_url, { method: 'POST', body: formData })).json();
            const saveRes = await jsonpRequest(`https://api.vk.com/method/photos.saveWallPhoto?group_id=${ownerId.replace('-', '')}&photo=${uploadRes.photo}&server=${uploadRes.server}&hash=${uploadRes.hash}&access_token=${config.vkAccessToken}&v=5.131`);
            if (saveRes.response?.length > 0) attachments = `photo${saveRes.response[0].owner_id}_${saveRes.response[0].id}`;
        } catch (e) { console.warn(e); }
    }

    const params: any = { access_token: config.vkAccessToken, owner_id: ownerId, message: text, from_group: '1', v: '5.131' };
    if (attachments) params.attachments = attachments;
    if (publishDate) params.publish_date = Math.floor(publishDate.getTime() / 1000).toString();
    return await jsonpRequest(`https://api.vk.com/method/wall.post?${new URLSearchParams(params).toString()}`);
};

async function jsonpRequest(url: string): Promise<any> {
    const callbackName = 'vk_callback_' + Math.round(Math.random() * 1000000);
    const script = document.createElement('script');
    return new Promise((resolve) => {
        // @ts-ignore
        window[callbackName] = (data: any) => {
            document.body.removeChild(script);
            // @ts-ignore
            delete window[callbackName];
            resolve(data);
        };
        script.src = `${url}&callback=${callbackName}`;
        document.body.appendChild(script);
    });
}

export const publishToWordPress = async (
    config: PublishingConfig, 
    title: string, 
    content: string, 
    imagesBase64: string[], 
    tags?: string, 
    publishDate?: Date,
    metaDescription?: string
) => {
    if (!config.wpUrl || !config.wpUsername || !config.wpAppPassword) throw new Error("WordPress не настроен");
    let baseUrl = config.wpUrl.replace(/\/$/, '');
    if (baseUrl.startsWith('http://') && !baseUrl.includes('localhost')) baseUrl = baseUrl.replace('http://', 'https://');
    const auth = safeBtoa(`${config.wpUsername}:${config.wpAppPassword}`);

    const request = async (endpoint: string, method: string, body?: any, isFile = false) => {
        const headers: any = { 'Authorization': `Basic ${auth}` };
        if (!isFile) headers['Content-Type'] = 'application/json';
        const res = await fetchWithTimeout(`${baseUrl}/wp-json/wp/v2/${endpoint}`, { method, headers, body });
        if (!res.ok) throw new Error(`WP Error: ${res.statusText}`);
        return res.json();
    };

    const mediaIds: number[] = [];
    for (let i = 0; i < imagesBase64.length; i++) {
        try {
            if (!imagesBase64[i] || imagesBase64[i].includes('placehold.co')) continue;
            const blob = await base64ToBlob(imagesBase64[i]);
            const formData = new FormData();
            formData.append('file', blob, `img-${Date.now()}-${i}.jpg`);
            formData.append('title', `${title} - ${i + 1}`);
            const media = await request('media', 'POST', formData, true);
            mediaIds.push(media.id);
        } catch (e) { console.warn(`Image ${i} upload failed`, e); }
    }

    let finalContent = content;
    finalContent += `\n\n---\n\n<!-- SEO INFO BLOCK -->\n`;
    if (metaDescription) finalContent += `**Description:** ${metaDescription}\n\n`;
    if (tags) {
        const fmtTags = tags.split(',').map(t => t.trim().replace(/\s+/g, '')).filter(Boolean).join(', ');
        finalContent += `**Tags:** ${fmtTags}\n`;
    }
    finalContent += `<!-- END SEO INFO BLOCK -->`;

    const postBody: any = {
        title,
        content: finalContent,
        status: publishDate ? 'future' : 'draft',
        excerpt: metaDescription || '',
        featured_media: mediaIds.length > 0 ? mediaIds[0] : undefined,
    };
    if (publishDate) postBody.date = publishDate.toISOString();

    return await request('posts', 'POST', JSON.stringify(postBody));
};

import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig } from '../types';
import { publishToTelegram, publishToVK, publishToWordPress } from '../services/publishingService';
import ReactMarkdown from 'react-markdown';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'telegram' | 'vk' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  // Editable State
  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [content, setContent] = useState(pack.siteArticle?.content || '');
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [metaDesc, setMetaDesc] = useState(pack.metaDescription || '');
  const [tgText, setTgText] = useState(pack.telegramPost?.content || '');
  const [vkText, setVkText] = useState(pack.vkPost?.content || '');

  const [publishing, setPublishing] = useState<string | null>(null);
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setContent(pack.siteArticle?.content || '');
    setHashtags(pack.siteArticle?.hashtags || '');
    setMetaDesc(pack.metaDescription || '');
    setTgText(pack.telegramPost?.content || '');
    setVkText(pack.vkPost?.content || '');
  }, [pack]);

  const handlePublish = async (platform: 'telegram' | 'vk' | 'wp') => {
    setPublishing(platform);
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      if (platform === 'telegram') {
        await publishToTelegram(pubConfig, tgText, pack.generatedImages[0], dateObj);
      } else if (platform === 'vk') {
        await publishToVK(pubConfig, vkText, pack.generatedImages[0], dateObj);
      } else if (platform === 'wp') {
        await publishToWordPress(pubConfig, headline, content, pack.generatedImages, hashtags, dateObj, metaDesc);
      }
      setPubStatus(prev => ({ ...prev, [platform]: { success: true, msg: 'Опубликовано!' } }));
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: e.message } }));
    } finally {
      setPublishing(null);
    }
  };

  const PublishControls = ({ platform, label }: { platform: 'wp' | 'vk' | 'telegram', label: string }) => (
    <div className="mb-4 bg-slate-50 p-3 rounded-lg border border-slate-200">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-2">
          <span className="text-xs font-bold uppercase text-slate-500">{label}</span>
          {pubStatus[platform]?.msg && <span className={`text-[10px] font-bold ${pubStatus[platform].success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus[platform].msg}</span>}
        </div>
        <div className="flex items-center gap-2">
          <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="text-xs border border-slate-300 rounded px-2 py-1 bg-white" />
          <button onClick={() => handlePublish(platform)} disabled={!!publishing} className="bg-brand-orange text-white text-[10px] px-3 py-1.5 rounded font-bold uppercase hover:bg-orange-600 disabled:opacity-50">
            {publishing === platform ? '...' : (scheduleDate ? 'Запланировать' : 'Опубликовать')}
          </button>
        </div>
      </div>
    </div>
  );

  if (pack.error) return <div className="p-10 text-center text-red-500 font-bold">{pack.error}</div>;

  return (
    <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200 flex flex-col h-full">
      <div className="bg-slate-50 border-b border-slate-200 p-2 flex justify-between items-center">
        <div className="flex space-x-1">
          {['site', 'telegram', 'vk', 'prompts'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-3 py-1.5 text-[10px] font-bold rounded uppercase ${activeTab === tab ? 'bg-white text-brand-orange shadow-sm border border-slate-200' : 'text-slate-500 hover:bg-slate-100'}`}>
              {tab === 'site' ? 'Сайт' : tab === 'telegram' ? 'TG' : tab === 'vk' ? 'VK' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className={`px-3 py-1 text-[10px] font-bold rounded uppercase border ${isEditing ? 'bg-brand-dark text-white' : 'bg-white text-brand-dark border-slate-300'}`}>
          {isEditing ? 'Готово' : 'Редактировать'}
        </button>
      </div>

      <div className="p-6 overflow-y-auto flex-1 custom-scrollbar">
        {activeTab === 'site' && (
          <div className="space-y-4">
            <PublishControls platform="wp" label="WordPress" />

            <div className="space-y-4">
              {isEditing ? (
                <>
                  <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full text-2xl font-bold font-serif-custom border-b border-slate-200 outline-none focus:border-brand-orange" placeholder="Заголовок..." />
                  <textarea value={metaDesc} onChange={e => setMetaDesc(e.target.value)} className="w-full text-xs p-2 bg-slate-50 rounded border border-slate-200 italic" rows={2} placeholder="Мета-описание..." />
