const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 35000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
        const response = await fetch(url, { ...options, signal: controller.signal });
        clearTimeout(id);
        return response;
    } catch (error: any) {
        clearTimeout(id);
        throw error;
    }
};

const base64ToBlob = async (base64: string): Promise<Blob> => {
  const res = await fetch(base64);
  return await res.blob();
};

const safeBtoa = (str: string) => {
    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g,
        (match, p1) => String.fromCharCode(parseInt(p1, 16))
    ));
};

export const publishToTelegram = async (config: PublishingConfig, text: string, imageBase64?: string, publishDate?: Date) => {
  if (!config.telegramBotToken || !config.telegramChatId) throw new Error("Telegram не настроен");

  const formData = new FormData();
  formData.append('chat_id', config.telegramChatId);
  formData.append('parse_mode', 'HTML'); 

  // Проверка отложенного постинга
  if (publishDate) {
      const now = new Date();
      const diffMinutes = (publishDate.getTime() - now.getTime()) / (1000 * 60);

      // Telegram позволяет планировать минимум на 10-30 секунд вперед. 
      // Мы берем 1 минуту для надежности. Если меньше - отправляем сразу.
      if (diffMinutes >= 1) {
          formData.append('schedule_date', Math.floor(publishDate.getTime() / 1000).toString());
      }
  }

  const endpoint = imageBase64 ? 'sendPhoto' : 'sendMessage';
  if (imageBase64) {
    const blob = await base64ToBlob(imageBase64);
    formData.append('photo', blob, 'image.jpg');
    formData.append('caption', text.substring(0, 1024)); 
  } else {
    formData.append('text', text);
  }

  const response = await fetchWithTimeout(`https://api.telegram.org/bot${config.telegramBotToken}/${endpoint}`, { method: 'POST', body: formData });
  const data = await response.json();

  if (!data.ok) {
      // Если это ошибка планирования (например, время в прошлом или не канал), пробуем отправить сразу
      if (data.description?.includes('scheduled') || data.description?.includes('time')) {
          formData.delete('schedule_date');
          const retryRes = await fetchWithTimeout(`https://api.telegram.org/bot${config.telegramBotToken}/${endpoint}`, { method: 'POST', body: formData });
          const retryData = await retryRes.json();
          if (!retryData.ok) throw new Error(`Telegram Error (Retry): ${retryData.description}`);
          return retryData;
      }
      throw new Error(`Telegram Error: ${data.description}`);
  }
  return data;
};

export const publishToVK = async (config: PublishingConfig, text: string, imageBase64?: string, publishDate?: Date) => {
    if (!config.vkAccessToken || !config.vkOwnerId) throw new Error("ВКонтакте не настроен");
    const ownerId = config.vkOwnerId.startsWith('-') ? config.vkOwnerId : `-${config.vkOwnerId}`; 
    let attachments = '';

    if (imageBase64) {
        try {
            const serverRes = await jsonpRequest(`https://api.vk.com/method/photos.getWallUploadServer?group_id=${ownerId.replace('-', '')}&access_token=${config.vkAccessToken}&v=5.131`);
            const blob = await base64ToBlob(imageBase64);
            const formData = new FormData();
            formData.append('photo', blob, 'image.jpg');
            const uploadRes = await (await fetch(serverRes.response.upload_url, { method: 'POST', body: formData })).json();
            const saveRes = await jsonpRequest(`https://api.vk.com/method/photos.saveWallPhoto?group_id=${ownerId.replace('-', '')}&photo=${uploadRes.photo}&server=${uploadRes.server}&hash=${uploadRes.hash}&access_token=${config.vkAccessToken}&v=5.131`);
            if (saveRes.response?.length > 0) attachments = `photo${saveRes.response[0].owner_id}_${saveRes.response[0].id}`;
        } catch (e) { console.warn(e); }
    }

    const params: any = { access_token: config.vkAccessToken, owner_id: ownerId, message: text, from_group: '1', v: '5.131' };
    if (attachments) params.attachments = attachments;
    if (publishDate) params.publish_date = Math.floor(publishDate.getTime() / 1000).toString();
    return await jsonpRequest(`https://api.vk.com/method/wall.post?${new URLSearchParams(params).toString()}`);
};

async function jsonpRequest(url: string): Promise<any> {
    const callbackName = 'vk_callback_' + Math.round(Math.random() * 1000000);
    const script = document.createElement('script');
    return new Promise((resolve) => {
        // @ts-ignore
        window[callbackName] = (data: any) => {
            document.body.removeChild(script);
            // @ts-ignore
            delete window[callbackName];
            resolve(data);
        };
        script.src = `${url}&callback=${callbackName}`;
        document.body.appendChild(script);
    });
}

export const publishToWordPress = async (
    config: PublishingConfig, 
    title: string, 
    content: string, 
    imagesBase64: string[], 
    tags?: string, 
    publishDate?: Date,
    metaDescription?: string
) => {
    if (!config.wpUrl || !config.wpUsername || !config.wpAppPassword) throw new Error("WordPress не настроен");
    let baseUrl = config.wpUrl.replace(/\/$/, '');
    if (baseUrl.startsWith('http://') && !baseUrl.includes('localhost')) baseUrl = baseUrl.replace('http://', 'https://');
    const auth = safeBtoa(`${config.wpUsername}:${config.wpAppPassword}`);

    const request = async (endpoint: string, method: string, body?: any, isFile = false) => {
        const headers: any = { 'Authorization': `Basic ${auth}` };
        if (!isFile) headers['Content-Type'] = 'application/json';
        const res = await fetchWithTimeout(`${baseUrl}/wp-json/wp/v2/${endpoint}`, { method, headers, body });
        if (!res.ok) throw new Error(`WP Error: ${res.statusText}`);
        return res.json();
    };

    const mediaIds: number[] = [];
    for (let i = 0; i < imagesBase64.length; i++) {
        try {
            if (!imagesBase64[i] || imagesBase64[i].includes('placehold.co')) continue;
            const blob = await base64ToBlob(imagesBase64[i]);
            const formData = new FormData();
            formData.append('file', blob, `img-${Date.now()}-${i}.jpg`);
            formData.append('title', `${title} - ${i + 1}`);
            const media = await request('media', 'POST', formData, true);
            mediaIds.push(media.id);
        } catch (e) { console.warn(`Image ${i} upload failed`, e); }
    }

    let finalContent = content;
    finalContent += `\n\n---\n\n<!-- SEO INFO BLOCK -->\n`;
    if (metaDescription) finalContent += `**Description:** ${metaDescription}\n\n`;
    if (tags) {
        const fmtTags = tags.split(',').map(t => t.trim().replace(/\s+/g, '')).filter(Boolean).join(', ');
        finalContent += `**Tags:** ${fmtTags}\n`;
    }
    finalContent += `<!-- END SEO INFO BLOCK -->`;

    const postBody: any = {
        title,
        content: finalContent,
        status: publishDate ? 'future' : 'draft',
        excerpt: metaDescription || '',
        featured_media: mediaIds.length > 0 ? mediaIds[0] : undefined,
    };
    if (publishDate) postBody.date = publishDate.toISOString();

    return await request('posts', 'POST', JSON.stringify(postBody));
};

import { GoogleGenAI } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const apiKey = process.env.API_KEY;
const ai = new GoogleGenAI({ apiKey: apiKey || '' });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const cleanMarkdown = (text: string) => {
    return text.replace(/\*\*/g, '').replace(/__/g, '').replace(/#/g, '').trim();
};

const cleanAndParseJSON = (text: string): any => {
    let clean = text.replace(/```json/gi, '').replace(/```/g, '').trim();
    try {
        return JSON.parse(clean);
    } catch (e) {
        const firstOpenBrace = clean.indexOf('{');
        const firstOpenBracket = clean.indexOf('[');
        let start = -1;
        if (firstOpenBrace !== -1 && firstOpenBracket !== -1) {
            start = Math.min(firstOpenBrace, firstOpenBracket);
        } else if (firstOpenBrace !== -1) {
            start = firstOpenBrace;
        } else if (firstOpenBracket !== -1) {
            start = firstOpenBracket;
        }

        if (start !== -1) {
            const isObject = clean[start] === '{';
            const end = isObject ? clean.lastIndexOf('}') : clean.lastIndexOf(']');
            if (end !== -1 && end > start) {
                try {
                    const substring = clean.substring(start, end + 1);
                    return JSON.parse(substring);
                } catch (innerE) {
                     console.warn("Advanced JSON extraction failed:", innerE);
                }
            }
        }
        throw new Error("AI вернул некорректные данные (JSON Parse Error).");
    }
};

export const generateDailyDigest = async (): Promise<DigestData> => {
  if (!apiKey) throw new Error("API Key не найден.");
  const model = "gemini-3-flash-preview"; 
  const dateStr = getCurrentDate();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ АНАЛИТИК ИЗДАНИЯ "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ".
    ТВОЯ ЗАДАЧА: Собрать 10 РЕАЛЬНЫХ новостей туризма за 24 часа.

    ПРАВИЛО №1: НИКАКИХ ФАНТАЗИЙ. Используй ТОЛЬКО информацию из результатов Google Search.
    ПРАВИЛО №2: ЦИТАТЫ ДОЛЖНЫ БЫТЬ ТОЧНЫМИ. Не придумывай слова экспертам.
    ПРАВИЛО №3: КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО ИСПОЛЬЗОВАТЬ Markdown (никаких **, __, #).
    ПРАВИЛО №4: ПОСЛЕ КАЖДОЙ НОВОСТИ В ДАЙДЖЕСТЕ ДОБАВЛЯЙ ССЫЛКУ (URL) НА ИСТОЧНИК.

    СТИЛЬ: Интеллектуальная ирония, сарказм, легкий юмор искушенного человека. Но ирония должна касаться реальных событий.

    СТРУКТУРА ДАЙДЖЕСТА (formattedDigestText):
    - Начинай строго с: "Новости туризма ${dateStr}".
    - Без приветствий.
    - Каждая новость: [Эмодзи] Текст новости. Источник: [URL]

    JSON:
    {
      "news": [{ "title": "...", "summary": "...", "location": "...", "sourceUrl": "...", "date": "..." }],
      "hacks": ["..."],
      "facts": ["..."],
      "formattedDigestText": "...",
      "formattedShortDigest": "...",
      "collagePrompt": "Atmospheric travel photography, professional, cinematic --ar 16:9"
    }
  `;

  const prompt = `Найди 10 актуальных новостей туризма за последние 24 часа. Используй только проверенные источники. Верни JSON.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: { tools: [{ googleSearch: {} }], systemInstruction: systemInstruction },
    });
    const parsed: DigestData = cleanAndParseJSON(response.text || "");

    parsed.formattedDigestText = cleanMarkdown(parsed.formattedDigestText);
    parsed.formattedShortDigest = cleanMarkdown(parsed.formattedShortDigest);

    parsed.news = (parsed.news || []).map((item: any, index: number) => ({
      ...item,
      id: `news-${index}-${Date.now()}`
    }));
    return parsed;
  } catch (error: any) {
    throw new Error(error.message);
  }
};

export const replaceNewsItems = async (currentNews: NewsItem[], excludeIds: string[]): Promise<NewsItem[]> => {
    const model = "gemini-3-flash-preview";
    const keptTitles = currentNews.filter(n => !excludeIds.includes(n.id)).map(n => n.title);
    const prompt = `Найди РЕАЛЬНУЮ замену для ${excludeIds.length} новостей. Используй Google Search. Исключи темы: ${keptTitles.join(', ')}. Верни JSON массив NewsItem.`;

    const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: { tools: [{ googleSearch: {} }] }
    });
    const newItems: any[] = cleanAndParseJSON(response.text || "[]");
    return newItems.map((item: any, index: number) => ({
        ...item,
        id: `news-replaced-${index}-${Date.now()}`
    }));
};

export const generateCreativeContent = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const models = ["gemini-2.5-flash", "gemini-3-flash-preview"];
  let lastError;

  const prompt = `
    ТЫ — ГЛАВНЫЙ КОЛУМНИСТ "ПЕРВОГО ТУРИСТИЧЕСКОГО".
    Стиль: Интеллектуальная ирония, сарказм, элегантный юмор.

    ЗАДАЧА:
    1. Статья для сайта (Markdown). Используй ТОЛЬКО факты из новости: "${newsItem.title}". Ничего не выдумывай. 
    2. Пост для Telegram (Остроумно).
    3. Пост для VK.

    ЕСЛИ В ТЕКСТЕ ЕСТЬ ЦИТАТЫ — ОНИ ДОЛЖНЫ БЫТЬ ПОДЛИННЫМИ.

    JSON:
    {
      "siteArticle": { "headline": "...", "content": "Markdown...", "hashtags": "слово1, слово2" },
      "telegramPost": { "content": "..." },
      "vkPost": { "content": "..." },
      "imagePrompts": ["Photo of...", "View of...", "Close up of..."],
      "metaDescription": "..."
    }
  `;

  for (const model of models) {
    try {
        const response = await ai.models.generateContent({
          model,
          contents: `Новость: "${newsItem.title}". Контекст: ${newsItem.summary}. Источник: ${newsItem.sourceUrl}. ${prompt}`,
          config: { tools: [{ googleSearch: {} }] }
        });
        const json = cleanAndParseJSON(response.text || "{}");

        const enforcedPrompts = (json.imagePrompts || []).slice(0, 3).map((p: string) => {
            let clean = p.replace(/--ar\s+\d+:\d+/g, '').trim();
            return `Hyper-realistic professional photography, 8k, cinematic lighting, ${clean} --ar 16:9 --no illustration, painting`;
        });

        while(enforcedPrompts.length < 3) enforcedPrompts.push(`Professional travel photo of ${newsItem.location || 'destination'} --ar 16:9`);

        return {
          newsId: newsItem.id,
          ...json,
          imagePrompts: enforcedPrompts,
          generatedImages: []
        };
    } catch (error: any) {
        lastError = error;
    }
  }
  throw new Error(`Ошибка: ${lastError?.message}`);
};

export const generateImage = async (prompt: string, aspectRatio: string = "16:9"): Promise<string | null> => {
    // Используем flash-image для стабильности
    const model = "gemini-2.5-flash-image";
    const cleanPrompt = prompt.replace(/--ar\s+\d+:\d+/g, '').trim();
    // Упрощаем промпт для обхода фильтров безопасности
    const finalPrompt = `Professional photography, high quality, ${cleanPrompt}`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: { parts: [{ text: finalPrompt }] },
            config: { imageConfig: { aspectRatio } }
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData?.data) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } catch (e) {
        console.error("Image gen error", e);
    }
    return null;
}

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
      await delay(8000); 
      const img = await generateImage(p);
      images.push(img || `https://placehold.co/1024x576/e2e8f0/475569?text=Image+Error`);
  }
  return images;
};

import React from 'react';
