export const NewsCard: React.FC<NewsCardProps> = ({ item, isSelected, onToggle, onMarkReplace, isMarkedForReplace }) => {
  return (
    <div 
      className={`relative p-6 rounded-xl border transition-all duration-300 group ${
        isMarkedForReplace
          ? 'border-red-200 bg-red-50 opacity-60 grayscale'
          : isSelected 
            ? 'border-brand-orange bg-white shadow-xl shadow-orange-100 ring-2 ring-brand-orange cursor-pointer transform scale-[1.02] z-10' 
            : 'border-slate-200 bg-white hover:border-brand-orange/50 hover:shadow-lg cursor-pointer'
      }`}
    >
      <div onClick={() => !isMarkedForReplace && onToggle(item.id)} className="h-full flex flex-col">
        <div className="flex justify-between items-start mb-3">
          <span className={`inline-block px-2 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md ${isMarkedForReplace ? 'bg-slate-200 text-slate-500' : 'text-white bg-brand-grey'}`}>
            {item.location || 'Мир'}
          </span>

          <div className="flex gap-2">
            <div className={`w-6 h-6 rounded-full border flex items-center justify-center transition-colors ${isSelected ? 'bg-brand-orange border-brand-orange' : 'border-slate-300 bg-white group-hover:border-brand-orange'}`}>
              {isSelected && (
                <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                </svg>
              )}
            </div>
          </div>
        </div>

        <h3 className={`text-lg font-bold mb-3 leading-snug font-sans ${isMarkedForReplace ? 'text-slate-400 line-through' : 'text-brand-dark group-hover:text-brand-orange transition-colors'}`}>
            {item.title}
        </h3>
        <p className={`text-sm leading-relaxed mb-4 flex-grow ${isMarkedForReplace ? 'text-slate-400' : 'text-brand-grey'}`}>
            {item.summary}
        </p>

        <div className="pt-3 border-t border-slate-100 flex flex-wrap gap-y-1 justify-between items-center text-[10px] text-slate-400 uppercase tracking-wide">
          {item.sourceUrl ? (
            <a 
              href={item.sourceUrl} 
              target="_blank" 
              rel="noopener noreferrer" 
              className="text-blue-500 hover:underline truncate max-w-[60%] flex items-center gap-1"
              onClick={(e) => e.stopPropagation()}
            >
              <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
              </svg>
              Источник
            </a>
          ) : (
            <span>Источник не указан</span>
          )}
          {item.date && (
             <span className="font-bold text-brand-grey">
               {item.date}
             </span>
          )}
        </div>
      </div>

      <button 
        onClick={(e) => {
            e.stopPropagation();
            onMarkReplace(item.id);
        }}
        className={`absolute -top-3 -right-3 w-8 h-8 rounded-full shadow-md flex items-center justify-center border transition-all z-20 ${
            isMarkedForReplace 
            ? 'bg-red-500 border-red-600 text-white hover:bg-red-600 rotate-180' 
            : 'bg-white border-slate-200 text-slate-400 hover:text-red-500 hover:border-red-200 opacity-0 group-hover:opacity-100'
        }`}
        title={isMarkedForReplace ? "Отменить удаление" : "Заменить новость"}
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            {isMarkedForReplace ? (
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            ) : (
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
            )}
        </svg>
      </button>
    </div>
  );
};

