export const generateCreativeContent = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const models = ["gemini-3-flash-preview", "gemini-2.5-flash"];
  let lastError;

  const prompt = `
    ТЫ — ГЛАВНЫЙ КОЛУМНИСТ "ПЕРВОГО ТУРИСТИЧЕСКОГО".
    Стиль: Интеллектуальный сарказм, тонкая ирония, лаконичность.

    ЗАДАЧА:
    1. Статья для сайта (Markdown). Основывайся ТОЛЬКО на фактах: "${newsItem.title}". Если есть эксперты — цитируй их дословно. 
    2. Пост для Telegram (Остроумно, хлестко).
    3. Пост для VK.

    БЕЗ ВЫДУМОК. БЕЗ ПОЛОЖИТЕЛЬНЫХ ПРИЛАГАТЕЛЬНЫХ, ЕСЛИ ОНИ НЕ ОПРАВДАНЫ ФАКТАМИ.

    JSON:
    {
      "siteArticle": { "headline": "...", "content": "Markdown...", "hashtags": "туризм, россия" },
      "telegramPost": { "content": "..." },
      "vkPost": { "content": "..." },
      "imagePrompts": ["Photo of modern tourist location in Russia...", "Close up of high tech travel detail...", "Atmospheric shot of..."],
      "metaDescription": "..."
    }
  `;

  for (const model of models) {
    try {
        const response = await ai.models.generateContent({
          model,
          contents: `Новость: "${newsItem.title}". Суть: ${newsItem.summary}. Источник: ${newsItem.sourceUrl}. ${prompt}`,
          config: { tools: [{ googleSearch: {} }] }
        });
        const json = cleanAndParseJSON(response.text || "{}");

        const enforcedPrompts = (json.imagePrompts || []).slice(0, 3).map((p: string) => {
            let clean = p.replace(/--ar\s+\d+:\d+/g, '').trim();
            return `Hyper-realistic travel photography, 8k resolution, cinematic, professional lighting, ${clean} --ar 16:9 --no text, illustration, low quality`;
        });

        while(enforcedPrompts.length < 3) enforcedPrompts.push(`Professional travel photo, Russian destination ${newsItem.location || ''} --ar 16:9`);

        return {
          newsId: newsItem.id,
          ...json,
          imagePrompts: enforcedPrompts,
          generatedImages: []
