import { PublishingConfig } from "../types";

const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 35000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
        const response = await fetch(url, { ...options, signal: controller.signal });
        clearTimeout(id);
        return response;
    } catch (error: any) {
        clearTimeout(id);
        throw error;
    }
};

const base64ToBlob = async (base64: string): Promise<Blob> => {
  const res = await fetch(base64);
  return await res.blob();
};

const safeBtoa = (str: string) => {
    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g,
        (match, p1) => String.fromCharCode(parseInt(p1, 16))
    ));
};

export const publishToTelegram = async (config: PublishingConfig, text: string, imageBase64?: string, publishDate?: Date) => {
  if (!config.telegramBotToken || !config.telegramChatId) throw new Error("Telegram не настроен");

  const formData = new FormData();
  formData.append('chat_id', config.telegramChatId);
  formData.append('parse_mode', 'HTML'); 

  // ТОЧНЫЙ РАСЧЕТ ВРЕМЕНИ ДЛЯ TELEGRAM
  if (publishDate) {
      const now = new Date();
      // Telegram API требует schedule_date в формате Unix Timestamp (секунды)
      // Дата должна быть минимум на 15-30 секунд в будущем.
      const diffSeconds = (publishDate.getTime() - now.getTime()) / 1000;

      if (diffSeconds > 45) { // Берем запас в 45 секунд
          const unixTime = Math.floor(publishDate.getTime() / 1000);
          formData.append('schedule_date', unixTime.toString());
          console.log(`[TG DEBUG] Пост запланирован на ${publishDate.toLocaleString()} (Unix: ${unixTime})`);
      } else {
          console.log("[TG DEBUG] Время слишком близко к текущему, отправляем сразу.");
      }
  }

  const endpoint = imageBase64 ? 'sendPhoto' : 'sendMessage';
  if (imageBase64) {
    const blob = await base64ToBlob(imageBase64);
    formData.append('photo', blob, 'image.jpg');
    // Лимит подписи в TG при фото - 1024 символа
    formData.append('caption', text.substring(0, 1024)); 
  } else {
    formData.append('text', text);
  }

  const response = await fetchWithTimeout(`https://api.telegram.org/bot${config.telegramBotToken}/${endpoint}`, { 
    method: 'POST', 
    body: formData 
  });

  const data = await response.json();

  if (!data.ok) {
      console.error("Telegram API Error:", data);
      // Если ошибка в дате (например, время ушло в прошлое пока шел запрос), пробуем отправить сразу
      if (data.description?.includes('schedule_date') || data.description?.includes('time')) {
          formData.delete('schedule_date');
          const retryRes = await fetchWithTimeout(`https://api.telegram.org/bot${config.telegramBotToken}/${endpoint}`, { method: 'POST', body: formData });
          const retryData = await retryRes.json();
          if (!retryData.ok) throw new Error(`Retry Telegram Error: ${retryData.description}`);
          return retryData;
      }
      throw new Error(`Telegram Error: ${data.description}`);
  }
  return data;
};

export const publishToVK = async (config: PublishingConfig, text: string, imageBase64?: string, publishDate?: Date) => {
    if (!config.vkAccessToken || !config.vkOwnerId) throw new Error("ВКонтакте не настроен");
    const ownerId = config.vkOwnerId.startsWith('-') ? config.vkOwnerId : `-${config.vkOwnerId}`; 
    let attachments = '';

    if (imageBase64) {
        try {
            const serverRes = await jsonpRequest(`https://api.vk.com/method/photos.getWallUploadServer?group_id=${ownerId.replace('-', '')}&access_token=${config.vkAccessToken}&v=5.131`);
            const blob = await base64ToBlob(imageBase64);
            const formData = new FormData();
            formData.append('photo', blob, 'image.jpg');
            const uploadRes = await (await fetch(serverRes.response.upload_url, { method: 'POST', body: formData })).json();
            const saveRes = await jsonpRequest(`https://api.vk.com/method/photos.saveWallPhoto?group_id=${ownerId.replace('-', '')}&photo=${uploadRes.photo}&server=${uploadRes.server}&hash=${uploadRes.hash}&access_token=${config.vkAccessToken}&v=5.131`);
            if (saveRes.response?.length > 0) attachments = `photo${saveRes.response[0].owner_id}_${saveRes.response[0].id}`;
        } catch (e) { console.warn(e); }
    }

    const params: any = { access_token: config.vkAccessToken, owner_id: ownerId, message: text, from_group: '1', v: '5.131' };
    if (attachments) params.attachments = attachments;
    if (publishDate) params.publish_date = Math.floor(publishDate.getTime() / 1000).toString();
    return await jsonpRequest(`https://api.vk.com/method/wall.post?${new URLSearchParams(params).toString()}`);
};

async function jsonpRequest(url: string): Promise<any> {
    const callbackName = 'vk_callback_' + Math.round(Math.random() * 1000000);
    const script = document.createElement('script');
    return new Promise((resolve) => {
        // @ts-ignore
        window[callbackName] = (data: any) => {
            document.body.removeChild(script);
            // @ts-ignore
            delete window[callbackName];
            resolve(data);
        };
        script.src = `${url}&callback=${callbackName}`;
        document.body.appendChild(script);
    });
}

export const publishToWordPress = async (
    config: PublishingConfig, 
    title: string, 
    content: string, 
    imagesBase64: string[], 
    tags?: string, 
    publishDate?: Date,
    metaDescription?: string
) => {
    if (!config.wpUrl || !config.wpUsername || !config.wpAppPassword) throw new Error("WordPress не настроен");
    let baseUrl = config.wpUrl.replace(/\/$/, '');
    if (baseUrl.startsWith('http://') && !baseUrl.includes('localhost')) baseUrl = baseUrl.replace('http://', 'https://');
    const auth = safeBtoa(`${config.wpUsername}:${config.wpAppPassword}`);

    const request = async (endpoint: string, method: string, body?: any, isFile = false) => {
        const headers: any = { 'Authorization': `Basic ${auth}` };
        if (!isFile) headers['Content-Type'] = 'application/json';
        const res = await fetchWithTimeout(`${baseUrl}/wp-json/wp/v2/${endpoint}`, { method, headers, body });
        if (!res.ok) throw new Error(`WP Error: ${res.statusText}`);
        return res.json();
    };

    const mediaIds: number[] = [];
    for (let i = 0; i < imagesBase64.length; i++) {
        try {
            if (!imagesBase64[i] || imagesBase64[i].includes('placehold.co')) continue;
            const blob = await base64ToBlob(imagesBase64[i]);
            const formData = new FormData();
            formData.append('file', blob, `img-${Date.now()}-${i}.jpg`);
            formData.append('title', `${title} - ${i + 1}`);
            const media = await request('media', 'POST', formData, true);
            mediaIds.push(media.id);
        } catch (e) { console.warn(`Image ${i} upload failed`, e); }
    }

    const postBody: any = {
        title,
        content: content,
        status: publishDate ? 'future' : 'draft',
        excerpt: metaDescription || '',
        featured_media: mediaIds.length > 0 ? mediaIds[0] : undefined,
    };
    if (publishDate) postBody.date = publishDate.toISOString();

    return await request('posts', 'POST', JSON.stringify(postBody));
};

