  formData.append('parse_mode', 'HTML'); 

  if (publishDate) {
      const now = new Date();
      // Разница в секундах
      const diffSeconds = (publishDate.getTime() - now.getTime()) / 1000;

      // Telegram требует минимум 10 секунд в будущем. Берем 30 для надежности.
