const apiKey = process.env.API_KEY;
const ai = new GoogleGenAI({ apiKey: apiKey || '' });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const cleanMarkdown = (text: string) => {
    if (!text) return "";
    return text
        .replace(/\*\*/g, '')
        .replace(/__/g, '')
        .replace(/#/g, '')
        .replace(/\[|\]/g, '')
        .replace(/\*/g, '')
        .trim();
};

export const generateDailyDigest = async (): Promise<DigestData> => {
  if (!apiKey) throw new Error("API Key не найден.");
  const model = "gemini-3-pro-preview"; 
  const dateStr = getCurrentDate();

  const systemInstruction = `
    ТЫ — РЕДАКЦИЯ ИЗДАНИЯ "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ". 
    МЫ ПИШЕМ ОТ ЛИЦА ВСЕЙ КОМАНДЫ (ИСПОЛЬЗУЙ "МЫ", "НАША РЕДАКЦИЯ"). НИКАКИХ КОЛУМНИСТОВ.
    ТВОЯ ЗАДАЧА: Собрать 10 РЕАЛЬНЫХ новостей туризма в России за последние 24 часа.

    СТИЛЬ: «Интеллектуальная ирония». 
    - Мы не красим всё черной краской. Хорошие новости (открытия, достижения, новые рейсы) описывай ПОЗИТИВНО, с доброй улыбкой и легкой иронией.
    - Проблемы подсвечивай тонким сарказмом, но без злой критики. Балансируй контент.
    - Никакой политики, только туризм, отели, транспорт и эмоции путешественников.

    ФОРМАТЫ:
    1. formattedShortDigest: [Эмодзи] + ОДНО краткое предложение на каждую из 10 новостей. БЕЗ ССЫЛОК.
    2. formattedDigestText: "Новости туризма ${dateStr}". На каждую новость: [Эмодзи] Заголовок + МИНИМУМ 3 развернутых предложения с аналитикой редакции. БЕЗ ССЫЛОК.
    3. collagePrompt: Промпт для фотореалистичного коллажа. ОБЯЗАТЕЛЬНО: На картинке должна быть четкая надпись на русском: "Новости туризма ${dateStr}".

    ВЕРНИ ТОЛЬКО ЧИСТЫЙ JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Собери 10 новостей туризма РФ за 24 часа. Тон: сбалансированная ирония редакции.`,
      config: { 
        tools: [{ googleSearch: {} }], 
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 4000 }
      },
    });

    const parsed = JSON.parse(response.text || "{}") as DigestData;

    parsed.formattedDigestText = cleanMarkdown(parsed.formattedDigestText);
    parsed.formattedShortDigest = cleanMarkdown(parsed.formattedShortDigest);

    parsed.news = (parsed.news || []).map((item: any, index: number) => ({
      ...item,
      id: `news-${index}-${Date.now()}`
    }));
    return parsed;
  } catch (error: any) {
    console.error("Digest Generation Error:", error);
    throw new Error("Не удалось собрать новости. Попробуйте еще раз.");
  }
};

export const generateCreativeContent = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview"; 
  const systemInstruction = `
    ТЫ — РЕДАКЦИЯ "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    Стиль: «Интеллектуальная ирония». Пиши от "мы". Избегай излишнего негатива.

    ТРЕБОВАНИЯ:
    1. СТАТЬЯ ДЛЯ САЙТА: Глубокая аналитика (СТРОГО ОТ 2500 ЗНАКОВ). 
       - Подзаголовки, цитаты "экспертов", детальный разбор.
       - Если новость хорошая — радуйся за индустрию. Если странная — иронизируй над абсурдом.
    2. ПОСТЫ СОЦСЕТЕЙ: Хлестко, без ссылок.

    ВЕРНИ ТОЛЬКО ЧИСТЫЙ JSON.
  `;

  try {
      const response = await ai.models.generateContent({
        model,
        contents: `Новость: "${newsItem.title}". Напиши огромную аналитическую статью (2500+ знаков) от лица редакции.`,
        config: { 
          tools: [{ googleSearch: {} }], 
          systemInstruction: systemInstruction,
          responseMimeType: "application/json",
          thinkingConfig: { thinkingBudget: 12000 }
        }
      });

      const json = JSON.parse(response.text || "{}");

      const enforcedPrompts = (json.imagePrompts || []).slice(0, 3).map((p: string) => {
          let clean = p.replace(/--ar\s+\d+:\d+/g, '').trim();
          return `Professional high-end travel photo, 8k, cinematic, ${clean} --ar 16:9`;
      });

      while(enforcedPrompts.length < 3) enforcedPrompts.push(`Travel photography of ${newsItem.location || 'Russia'} --ar 16:9`);

      return {
        newsId: newsItem.id,
        ...json,
        imagePrompts: enforcedPrompts,
        generatedImages: []
      };
  } catch (error: any) {
      console.error("Content Generation Error:", error);
      throw new Error(`Ошибка генерации контента. Проверьте соединение.`);
  }
};

export const generateImage = async (prompt: string, aspectRatio: string = "16:9"): Promise<string | null> => {
    const model = "gemini-2.5-flash-image";
    const cleanPrompt = prompt.replace(/--ar\s+\d+:\d+/g, '').trim();
    const finalPrompt = `Photorealistic travel masterpiece, 8k, professional, ${cleanPrompt}`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: { parts: [{ text: finalPrompt }] },
            config: { imageConfig: { aspectRatio } }
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData?.data) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } catch (e) {
        console.error("Image gen error", e);
    }
    return null;
}

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
      await delay(8000); 
      const img = await generateImage(p);
      images.push(img || `https://placehold.co/1024x576/e2e8f0/475569?text=Image+Error`);
  }
  return images;
};

export const replaceNewsItems = async (currentNews: NewsItem[], excludeIds: string[]): Promise<NewsItem[]> => {
    const model = "gemini-3-pro-preview";
    const keptTitles = currentNews.filter(n => !excludeIds.includes(n.id)).map(n => n.title);
    const prompt = `Найди актуальную замену для ${excludeIds.length} новостей туризма РФ. Исключи: ${keptTitles.join(', ')}. Стиль редакции. Верни JSON массив NewsItem.`;

    const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: { 
          tools: [{ googleSearch: {} }],
          responseMimeType: "application/json",
          thinkingConfig: { thinkingBudget: 4000 }
        }
    });
    const newItems = JSON.parse(response.text || "[]");
    return newItems.map((item: any, index: number) => ({
        ...item,
        id: `news-replaced-${index}-${Date.now()}`
    }));
};

