const apiKey = process.env.API_KEY;
const ai = new GoogleGenAI({ apiKey: apiKey || '' });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const cleanMarkdown = (text: string) => {
    if (!text) return "";
    return text
        .replace(/\*\*/g, '')
        .replace(/__/g, '')
        .replace(/#/g, '')
        .replace(/\[|\]/g, '')
        .replace(/\*/g, '')
        .trim();
};

/**
 * Продвинутый парсер JSON, который извлекает объект из любого текстового мусора
 */
const robustJSONParse = (text: string): any => {
    if (!text) throw new Error("Пустой ответ от AI.");

    // Пытаемся очистить от markdown-оберток
    let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();

    try {
        return JSON.parse(cleaned);
    } catch (e) {
        // Если не вышло, ищем границы объекта { ... } или массива [ ... ]
        const firstBrace = cleaned.indexOf('{');
        const firstBracket = cleaned.indexOf('[');
        let start = -1;

        if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) start = firstBrace;
        else if (firstBracket !== -1) start = firstBracket;

        if (start !== -1) {
            const char = cleaned[start];
            const end = char === '{' ? cleaned.lastIndexOf('}') : cleaned.lastIndexOf(']');
            if (end !== -1 && end > start) {
                try {
                    return JSON.parse(cleaned.substring(start, end + 1));
                } catch (innerE) {
                    console.error("Deep parse failed", innerE);
                }
            }
        }
        throw new Error("AI вернул данные в неверном формате. Попробуйте нажать кнопку еще раз.");
    }
};

