    const prompt = `Найди 100% реальные новости туризма РФ для замены. Исключи: ${keptTitles.join(', ')}. Тон редакции. Верни JSON массив.`;

    const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: { 
          tools: [{ googleSearch: {} }],
          responseMimeType: "application/json",
          thinkingConfig: { thinkingBudget: 4000 }
        }
    });
