/**
 * Продвинутый парсер JSON, который извлекает объект из любого текстового мусора.
 * Полезен, когда модель добавляет примечания или источники заземления вне JSON блока.
 */
const robustJSONParse = (text: string): any => {
    if (!text) throw new Error("Пустой ответ от AI.");

    // 1. Пытаемся очистить от markdown-оберток
    let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();

    // 2. Простой парсинг
    try {
        return JSON.parse(cleaned);
    } catch (e) {
        // 3. Регулярное выражение для поиска JSON объектов или массивов
        const jsonMatch = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        if (jsonMatch) {
            try {
                return JSON.parse(jsonMatch[0]);
            } catch (innerE) {
                // Если внутри JSON есть некорректные символы, пробуем найти самый длинный блок
                const firstBrace = cleaned.indexOf('{');
                const lastBrace = cleaned.lastIndexOf('}');
                if (firstBrace !== -1 && lastBrace > firstBrace) {
                   try {
                       return JSON.parse(cleaned.substring(firstBrace, lastBrace + 1));
                   } catch (deepE) {
                       console.error("Deep parse failed", deepE);
                   }
                }
            }
        }
        throw new Error("AI вернул данные в неверном формате. Попробуйте еще раз.");
    }
};

