};

export const generateCreativeContent = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview"; 
  const systemInstruction = `
    ТЫ — РЕДАКЦИЯ "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ЗАПРЕЩЕНО: выдумывать персонажей, экспертов или мнения, которых нет в новости.
    ЗАПРЕЩЕНО: использовать любые символы разметки (**, ***, #, <b>). Только чистый текст.
    СТИЛЬ: Едкие новости, сарказм над ситуацией, никакой нудной аналитики.
    ДЛИНА СТАТЬИ: Минимум 2500 знаков. Глубоко, но в новостном стиле.

    ВЕРНИ JSON:
    {
      "siteArticle": { "headline": "Заголовок", "content": "Текст статьи", "hashtags": "туризм, рф" },
      "telegramPost": { "content": "Пост для ТГ" },
      "vkPost": { "content": "Пост для ВК" },
      "imagePrompts": ["промпт 1", "промпт 2", "промпт 3"],
      "metaDescription": "Описание для SEO"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью и посты по новости: ${newsItem.title}. Фактура: ${newsItem.summary}. Чистый текст без спецсимволов.`,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 12000 }
      },
    });

    const parsed = robustJSONParse(response.text || "");

    parsed.siteArticle.content = cleanMarkdown(parsed.siteArticle.content);
    parsed.siteArticle.headline = cleanMarkdown(parsed.siteArticle.headline);
    parsed.telegramPost.content = cleanMarkdown(parsed.telegramPost.content);
    parsed.vkPost.content = cleanMarkdown(parsed.vkPost.content);

    return {
      newsId: newsItem.id,
      ...parsed
    };
  } catch (error: any) {
