      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `High quality professional travel photography, photorealistic, cinematic lighting, 8k, NO TEXT, NO LABELS, NO LETTERS, strictly photo: ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (error) {
    return ""; 
  }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const prompt of prompts.slice(0, 3)) {
    const img = await generateImage(prompt);
    if (img) images.push(img);
    await delay(3000);
  }
  while (images.length < 3) images.push("https://placehold.co/600x337?text=Image+Error");
  return images;
};

export const replaceNewsItems = async (currentNews: NewsItem[], toReplaceIds: string[]): Promise<NewsItem[]> => {
  const model = "gemini-3-pro-preview";
  const today = getCurrentDate();
  const existing = currentNews.map(n => n.title).join(", ");

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди ${toReplaceIds.length} альтернативных новостей за 48 часов с ${today}. Исключи: ${existing}.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: `ТЫ — РЕДАКЦИЯ. Верни JSON объектов NewsItem без спецсимволов.`,
        responseMimeType: "application/json"
      },
    });
    const newItems = robustJSONParse(response.text || "[]");
    return newItems.map((item: any, index: number) => ({
      ...item,
      id: `replacement-${index}-${Date.now()}`
    }));
  } catch (error) {
    return [];
  }
};

