      contents: `Найди ${toReplaceIds.length} альтернативных новостей туризма РФ за 48 часов с ${today}. Исключи: ${existing}.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: `ТЫ — РЕДАКЦИЯ. Верни JSON списка объектов NewsItem без спецсимволов. Новости строго за последние 48 часов.`,
        responseMimeType: "application/json"
      },
