/**
 * Фиксируем дату: сегодня 3 января 2026 года.
 */
const getCurrentDate = () => {
  return "3 января 2026 года";
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Полное удаление любых символов разметки.
 */
const cleanMarkdown = (text: string) => {
    if (!text) return "";
    return text
        .replace(/\*\*\*/g, '')
        .replace(/\*\*/g, '')
        .replace(/\*/g, '')
        .replace(/__/g, '')
        .replace(/#/g, '')
        .replace(/\[|\]/g, '')
        .replace(/<[^>]*>?/gm, '') 
        .replace(/&nbsp;/g, ' ')
        .replace(/\\n/g, '\n')
        .replace(/\r/g, '')
        .trim();
};

const robustJSONParse = (text: string): any => {
    if (!text) throw new Error("Пустой ответ от системы.");
    // Агрессивный поиск JSON в ответе
    let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
    try {
        return JSON.parse(cleaned);
    } catch (e) {
        const jsonMatch = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        if (jsonMatch) {
            try {
                return JSON.parse(jsonMatch[0]);
            } catch (innerE) {
                const firstBrace = cleaned.indexOf('{');
                const lastBrace = cleaned.lastIndexOf('}');
                if (firstBrace !== -1 && lastBrace > firstBrace) {
                   try {
                       return JSON.parse(cleaned.substring(firstBrace, lastBrace + 1));
                   } catch (deepE) {}
                }
            }
        }
        throw new Error("Ошибка формата данных ИИ.");
    }
};

