import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const cleanMarkdown = (text: string) => {
    if (!text) return "";
    return text
        .replace(/\*\*\*/g, '')
        .replace(/\*\*/g, '')
        .replace(/\*/g, '')
        .replace(/__/g, '')
        .replace(/#/g, '')
        .replace(/\[|\]/g, '')
        .replace(/<[^>]*>?/gm, '') 
        .replace(/&nbsp;/g, ' ')
        .replace(/\\n/g, '\n')
        .trim();
};

const robustJSONParse = (text: string): any => {
    let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
    try {
        return JSON.parse(cleaned);
    } catch (e) {
        const jsonMatch = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        if (jsonMatch) return JSON.parse(jsonMatch[0]);
        throw new Error("ИИ выдал некорректный формат.");
    }
};

export const generateDailyDigest = async (globalSarcasm: number = 5): Promise<DigestData> => {
  const model = "gemini-3-pro-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ИРОНИЧНЫЙ РЕДАКТОР В СТИЛЕ ЖВАНЕЦКОГО. 
    СЕГОДНЯ: ${today}.
    ЗАДАЧА: Найти 10 РЕАЛЬНЫХ новостей туризма в РФ за последние 48 часов.

    СТИЛЬ: 
    - Лаконично, остроумно.
    - Никаких символов разметки (**, #, []).
    - КОЛЛАЖ: Промпт должен запрашивать текст "НОВОСТИ ТУРИЗМА" на русском языке.

    ВЕРНИ JSON:
    {
      "news": [{ "title": "...", "summary": "...", "location": "...", "sourceUrl": "...", "date": "..." }],
      "hacks": ["..."],
      "facts": ["..."],
      "formattedDigestText": "...",
      "formattedShortDigest": "...",
      "collagePrompt": "High quality travel collage, photorealistic, with stylized Russian text 'НОВОСТИ ТУРИЗМА' in the center, 8k, professional lighting"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди новости на ${today}. Ирония: ${globalSarcasm}/10.`,
      config: { tools: [{ googleSearch: {} }], systemInstruction },
    });
    const parsed = robustJSONParse(response.text || "");
    parsed.news = (parsed.news || []).map((n: any, i: number) => ({ ...n, id: `n-${i}-${Date.now()}` }));
    return parsed;
  } catch (error) {
    throw new Error("Ошибка поиска новостей.");
  }
};

export const generateCreativeContent = async (newsItem: NewsItem, sarcasmLevel: number): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — СМЕСЬ ЖВАНЕЦКОГО И ХМЕЛЕВСКОЙ. СЕГОДНЯ ${today}.
    УРОВЕНЬ САРКАЗМА: ${sarcasmLevel} из 10.
    ЗАДАЧА: Написать статью (2500+ знаков) и посты.

    ПРАВИЛА:
    - Пиши ЧИСТЫМ ТЕКСТОМ. ЗАПРЕЩЕНО: **, ***, #, [].
    - ХЕШТЕГИ: Строго без знака #, только слова через запятую.
    - СТИЛЬ: Ироничное наблюдение за ситуацией.
    - ИЗОБРАЖЕНИЯ: Промпты для ФОТОГРАФИЙ 16:9 БЕЗ ТЕКСТА.

    ВЕРНИ JSON:
    {
      "siteArticle": { "headline": "...", "content": "...", "hashtags": "туризм, новости, путешествия" },
      "telegramPost": { "content": "..." },
      "vkPost": { "content": "..." },
      "imagePrompts": ["...", "...", "..."],
      "metaDescription": "..."
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Сарказм: ${sarcasmLevel}/10.`,
      config: { systemInstruction, responseMimeType: "application/json" },
    });
    const parsed = robustJSONParse(response.text || "");
    parsed.siteArticle.content = cleanMarkdown(parsed.siteArticle.content) + `\n\nИсточник: ${newsItem.sourceUrl}`;
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    throw new Error(`Ошибка генерации для: ${newsItem.title}`);
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `STRICTLY ASPECT RATIO 16:9, high quality professional photography: ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch { return ""; }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await delay(3000);
  }
  while (images.length < 3) images.push("https://placehold.co/1600x900?text=Image+Error");
  return images;
};

import React, { useState, useEffect } from 'react';
