        <div className="mt-4 pt-4 border-t border-slate-50 flex justify-between items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest">
           <span>{item.date || 'АКТУАЛЬНО'}</span>
           <span className={isSelected ? 'text-brand-orange' : ''}>{isSelected ? 'ВЫБРАНО' : 'ВЫБРАТЬ'}</span>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const cleanMarkdown = (text: string) => {
    if (!text) return "";
    return text
        .replace(/\*\*\*/g, '')
        .replace(/\*\*/g, '')
        .replace(/\*/g, '')
        .replace(/__/g, '')
        .replace(/#/g, '')
        .replace(/\[|\]/g, '')
        .replace(/<[^>]*>?/gm, '') 
        .replace(/&nbsp;/g, ' ')
        .replace(/\\n/g, '\n')
        .trim();
};

const robustJSONParse = (text: string): any => {
    let cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
    try {
        return JSON.parse(cleaned);
    } catch (e) {
        const jsonMatch = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        if (jsonMatch) return JSON.parse(jsonMatch[0]);
        throw new Error("ИИ выдал некорректный формат.");
    }
};

export const generateDailyDigest = async (globalSarcasm: number = 5): Promise<DigestData> => {
  const model = "gemini-3-pro-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ИРОНИЧНЫЙ ВЕДУЩИЙ РЕДАКЦИИ "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ". 
    СЕГОДНЯ: ${today}.
    ЗАДАЧА: Найти 10 РЕАЛЬНЫХ новостей туризма в РФ за последние 48 часов.

    ПРАВИЛА ОФОРМЛЕНИЯ ТЕКСТА:
    - formattedDigestText (Дайджест): Перед каждой новостью ОБЯЗАТЕЛЬНО ставь подходящий тематический ЭМОДЗИ. Стиль: краткое ироничное изложение.
    - formattedShortDigest (Бегущая строка): Формат "ЭМОДЗИ Новость — Краткое пояснение". Каждая новость с новой строки.
    - Никаких символов разметки (**, #, []).
    - КОЛЛАЖ: Промпт должен требовать текст "НОВОСТИ ТУРИЗМА" на русском языке в центре кадра, формат 16:9.

    ВЕРНИ JSON:
    {
      "news": [{ "title": "...", "summary": "...", "location": "...", "sourceUrl": "...", "date": "..." }],
      "hacks": ["..."],
      "facts": ["..."],
      "formattedDigestText": "...",
      "formattedShortDigest": "...",
      "collagePrompt": "Cinematic travel collage, photorealistic, blurred background, with clear bold Russian text 'НОВОСТИ ТУРИЗМА' in the center, 16:9 aspect ratio, 8k, professional lighting"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди новости на ${today}. Степень иронии: ${globalSarcasm}/10.`,
      config: { tools: [{ googleSearch: {} }], systemInstruction },
    });
    const parsed = robustJSONParse(response.text || "");
    parsed.news = (parsed.news || []).map((n: any, i: number) => ({ ...n, id: `n-${i}-${Date.now()}` }));
    return parsed;
  } catch (error) {
    throw new Error("Ошибка поиска новостей.");
  }
};

export const generateCreativeContent = async (newsItem: NewsItem, sarcasmLevel: number): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — РЕДАКЦИЯ "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ". ПИШИ ОТ ИМЕНИ РЕДАКЦИИ (МЫ), А НЕ ОТ ПЕРВОГО ЛИЦА (Я).
    СЕГОДНЯ: ${today}.
    УРОВЕНЬ САРКАЗМА: ${sarcasmLevel} из 10.

    ЗАДАЧА: Написать статью (2500+ знаков) и посты для соцсетей.

    ПРАВИЛА:
    - ПОЛНОЕ ОТСУТСТВИЕ РАЗМЕТКИ: Никаких **, ***, #, []. Только чистый текст.
    - ХЕШТЕГИ: Строго БЕЗ знака #, только слова через запятую.
    - СТИЛЬ: "Первый Туристический" — это смесь Жванецкого и профессионального тревел-аналитика.
    - ИЗОБРАЖЕНИЯ: Промпты для фотографий БЕЗ ТЕКСТА, формат 16:9.

    ВЕРНИ JSON:
    {
      "siteArticle": { "headline": "...", "content": "...", "hashtags": "туризм, новости, рф" },
      "telegramPost": { "content": "..." },
      "vkPost": { "content": "..." },
      "imagePrompts": ["High quality 16:9 photo of...", "Professional 16:9 travel shot of...", "Detailed 16:9 wide shot of..."],
      "metaDescription": "..."
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Сарказм: ${sarcasmLevel}/10. Пиши от лица 'Первого Туристического'.`,
      config: { systemInstruction, responseMimeType: "application/json" },
    });
    const parsed = robustJSONParse(response.text || "");
    parsed.siteArticle.content = cleanMarkdown(parsed.siteArticle.content) + `\n\nИсточник: ${newsItem.sourceUrl}`;
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    throw new Error(`Ошибка генерации для: ${newsItem.title}`);
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `STRICTLY 16:9 ASPECT RATIO. Wide format travel photography. ${prompt}` }] },
      config: { 
        imageConfig: { 
          aspectRatio: "16:9" 
        } 
      }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) { 
    console.error("Image gen error:", err);
    return ""; 
  }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await delay(3000); // Чтобы не превышать лимиты
  }
  while (images.length < 3) images.push("https://placehold.co/1600x900?text=Error+Generating+Image");
  return images;
};

import React, { useState, useEffect } from 'react';
import { generateDailyDigest, generateCreativeContent, generateImagesForPack, generateImage } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { NewsCard } from './components/NewsCard';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { AddNewsModal } from './components/AddNewsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [sarcasmLevels, setSarcasmLevels] = useState<Record<string, number>>({});
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isAddNewsOpen, setIsAddNewsOpen] = useState(false);

  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    telegramBotToken: '', telegramChatId: '', vkAccessToken: '', vkOwnerId: '', wpUrl: '', wpUsername: 'admin', wpAppPassword: '' 
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { setPubConfig(prev => ({ ...prev, ...JSON.parse(saved) })); } catch (e) {}
    }
  }, []);

  const handleStartResearch = async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Ищу свежие новости...");
    try {
      const data = await generateDailyDigest();
      setDigest(data);
      setAppState(AppState.SELECTING);
      if (data.collagePrompt) {
          generateImage(data.collagePrompt).then(img => {
             if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
          });
      }
    } catch (e: any) {
      setErrorMsg(e.message);
      setAppState(AppState.ERROR);
    }
  };

  const toggleNewsSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) {
        const newLevels = { ...sarcasmLevels };
        delete newLevels[id];
        setSarcasmLevels(newLevels);
        return prev.filter(i => i !== id);
      }
      if (prev.length >= MAX_SELECTION) return prev;
      setSarcasmLevels(l => ({ ...l, [id]: 5 }));
      return [...prev, id];
    });
  };

  const updateSarcasm = (id: string, val: number) => {
    setSarcasmLevels(prev => ({ ...prev, [id]: val }));
  };

  const handleGenerateContent = async () => {
    if (selectedNewsIds.length === 0) return;
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < selectedItems.length; i++) {
      const item = selectedItems[i];
      const level = sarcasmLevels[item.id] || 5;
      setStatusMessage(`Пишу материал от лица редакции (${i+1}/${selectedItems.length})...`);
      try {
        const content = await generateCreativeContent(item, level);
        setStatusMessage(`Рисую 16:9 кадры для "${item.title.substring(0, 20)}..."`);
        const images = await generateImagesForPack(content.imagePrompts);
        setGeneratedResults(prev => [...prev, { ...content, generatedImages: images }]);
      } catch (err: any) {
        console.error(err);
      }
    }
    setAppState(AppState.COMPLETED);
  };

  const todayDisplay = new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });

  return (
    <div className="min-h-screen bg-[#f5f5f7] pb-10">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />
      <AddNewsModal isOpen={isAddNewsOpen} onClose={() => setIsAddNewsOpen(false)} onAdd={(n) => setDigest(prev => prev ? ({...prev, news:[{...n, id:Date.now().toString()}, ...prev.news]}) : null)} />

      <nav className="bg-brand-dark h-16 flex items-center px-6 sticky top-0 z-50">
        <h1 className="text-white font-bold uppercase tracking-tighter text-xl">ПЕРВЫЙ <span className="text-brand-orange">ТУРИСТИЧЕСКИЙ</span></h1>
        <div className="ml-4 px-2 py-0.5 bg-brand-orange/20 border border-brand-orange/40 rounded text-[10px] text-brand-orange font-black uppercase">{todayDisplay}</div>
        <button onClick={() => setIsSettingsOpen(true)} className="ml-auto text-xl">⚙️</button>
      </nav>

      <main className="max-w-[1400px] mx-auto p-6">
        {appState === AppState.ERROR && (
           <div className="text-center py-20 bg-white rounded-3xl shadow-xl">
              <div className="text-6xl mb-6">⚠️</div>
              <h2 className="text-2xl text-red-500 font-bold mb-4">{errorMsg}</h2>
              <button onClick={() => setAppState(AppState.IDLE)} className="bg-brand-orange text-white px-8 py-3 rounded-xl font-bold uppercase tracking-widest">Вернуться</button>
           </div>
        )}

        {appState === AppState.IDLE && (
          <div className="flex flex-col items-center py-20 bg-white rounded-3xl shadow-xl border border-slate-100">
            <div className="w-24 h-24 bg-brand-orange/10 rounded-full flex items-center justify-center mb-8">
               <span className="text-4xl">🗞️</span>
            </div>
            <h2 className="text-4xl font-black mb-4 uppercase text-brand-dark">Эфир Первого Туристического</h2>
            <p className="text-slate-500 mb-8 max-w-md text-center">Профессиональная тревел-аналитика с фирменным ироничным почерком редакции.</p>
            <button onClick={handleStartResearch} className="px-12 py-4 bg-brand-orange text-white font-bold rounded-xl uppercase tracking-widest hover:scale-105 transition-all shadow-xl shadow-orange-200">Запустить поиск</button>
          </div>
        )}

        {(appState === AppState.SEARCHING || appState === AppState.GENERATING_CONTENT) && (
          <div className="flex flex-col items-center py-40">
            <div className="relative">
                <div className="w-20 h-20 border-4 border-brand-orange border-t-transparent rounded-full animate-spin mb-8"></div>
                <div className="absolute inset-0 flex items-center justify-center font-bold text-xs text-brand-orange uppercase animate-pulse">AI</div>
            </div>
            <h3 className="text-2xl font-bold text-brand-dark tracking-tight">{statusMessage}</h3>
            <p className="text-slate-400 mt-2 font-medium">Это может занять минуту. Готовим лучший контент.</p>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div>
            <div className="flex justify-between items-center mb-8 bg-white/80 p-6 rounded-2xl border border-slate-100 backdrop-blur sticky top-20 z-30 shadow-sm">
               <div>
                  <h2 className="text-2xl font-bold uppercase text-brand-dark">Темы для разбора</h2>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Выберите до {MAX_SELECTION} новостей и настройте иронию</p>
               </div>
               <div className="flex gap-4">
                  <button onClick={() => setIsAddNewsOpen(true)} className="px-4 py-2 border border-slate-300 rounded-xl font-bold text-xs uppercase hover:bg-slate-50 transition-colors">+ Своя тема</button>
                  <button onClick={handleGenerateContent} disabled={selectedNewsIds.length === 0} className={`px-8 py-2 rounded-xl font-bold text-xs uppercase transition-all ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white shadow-lg shadow-orange-200' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
                    Сформировать выпуск ({selectedNewsIds.length})
                  </button>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
               {digest.news.map(n => (
                 <NewsCard 
                    key={n.id} 
                    item={n} 
                    isSelected={selectedNewsIds.includes(n.id)} 
                    onToggle={toggleNewsSelection} 
                    onMarkReplace={() => {}} 
                    isMarkedForReplace={false}
                    sarcasmValue={sarcasmLevels[n.id] || 5}
                    onSarcasmChange={(val) => updateSarcasm(n.id, val)}
                 />
               ))}
            </div>
          </div>
        )}

        {appState === AppState.COMPLETED && (
           <div className="space-y-8">
              <div className="flex items-center justify-between">
                  <h2 className="text-2xl font-black uppercase text-brand-dark">Готовый выпуск</h2>
                  <button onClick={() => setAppState(AppState.IDLE)} className="text-xs font-bold text-slate-400 uppercase hover:text-brand-orange transition-colors">Сбросить и начать заново</button>
              </div>
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                  <div className="lg:col-span-1 h-full">{digest && <DigestPostViewer digest={digest} pubConfig={pubConfig} />}</div>
                  <div className="lg:col-span-2 space-y-8">
                    {generatedResults.map(res => <ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />)}
                  </div>
              </div>
           </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToTelegram, publishToVK } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [copied, setCopied] = useState(false);
  const [publishing, setPublishing] = useState<string | null>(null);
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  const getTextToUse = () => {
      const rawText = activeView === 'long' ? digest.formattedDigestText : digest.formattedShortDigest;
      // Чистим только артефакты Markdown, оставляя эмодзи
      return rawText.replace(/\*\*/g, '').replace(/\*/g, '').replace(/__/g, '').trim();
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(getTextToUse());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePublish = async (platform: 'telegram' | 'vk') => {
    setPublishing(platform);
    setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: '' } }));

    const textToSend = getTextToUse();
    const imageToSend = activeView === 'long' ? digest.collageImage : undefined;
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      if (platform === 'telegram') {
        await publishToTelegram(pubConfig, textToSend, imageToSend, dateObj);
        setPubStatus(prev => ({ ...prev, telegram: { success: true, msg: scheduleDate ? 'Запланировано!' : 'Отправлено!' } }));
      }
      else if (platform === 'vk') {
        await publishToVK(pubConfig, textToSend, imageToSend, dateObj);
        setPubStatus(prev => ({ ...prev, vk: { success: true, msg: scheduleDate ? 'Запланировано!' : 'Опубликовано!' } }));
      }
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: e.message } }));
    } finally {
      setPublishing(null);
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200 h-full flex flex-col">
      <div className="bg-slate-50 border-b border-slate-200 p-3 flex justify-between items-center">
        <div className="flex gap-2">
            <button 
                onClick={() => setActiveView('long')}
                className={`text-[10px] px-3 py-1.5 rounded-lg font-bold uppercase transition-all tracking-wider ${activeView === 'long' ? 'bg-white shadow-sm text-brand-orange border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
            >
                Дайджест
            </button>
            <button 
                onClick={() => setActiveView('short')}
                className={`text-[10px] px-3 py-1.5 rounded-lg font-bold uppercase transition-all tracking-wider ${activeView === 'short' ? 'bg-white shadow-sm text-brand-orange border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
            >
                Бегущая строка
            </button>
        </div>
        <button 
          onClick={handleCopy}
          className={`text-[10px] px-3 py-1.5 rounded-lg transition-all uppercase font-black ${copied ? 'bg-green-500 text-white' : 'bg-brand-orange/10 text-brand-orange hover:bg-brand-orange/20'}`}
        >
          {copied ? 'УСПЕШНО' : 'КОПИРОВАТЬ'}
        </button>
      </div>

      <div className="p-0 overflow-y-auto custom-scrollbar flex-1 relative flex flex-col min-h-[500px]">
        {activeView === 'long' && (
            <div className="relative h-64 w-full bg-slate-900 group shrink-0">
            {digest.collageImage ? (
                <img 
                src={digest.collageImage} 
                alt="Digest Collage" 
                className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105 opacity-90"
                />
            ) : (
                <div className="w-full h-full flex flex-col items-center justify-center space-y-4">
                    <div className="w-8 h-8 border-2 border-brand-orange/30 border-t-brand-orange rounded-full animate-spin"></div>
                    <div className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Генерация обложки 16:9...</div>
                </div>
            )}
            <div className="absolute inset-0 bg-gradient-to-t from-brand-dark via-brand-dark/20 to-transparent"></div>
            <div className="absolute bottom-4 left-5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
                   <span className="text-[10px] text-white/70 font-black uppercase tracking-[0.2em]">Live Editorial</span>
                </div>
                <h2 className="text-white font-black text-xl uppercase tracking-tighter italic">Вечерний дайджест</h2>
            </div>
            </div>
        )}

        <div className="p-4 bg-white border-b border-slate-100 space-y-4 shadow-inner">
           <div className="flex items-center gap-3 bg-slate-50 p-2.5 rounded-xl border border-slate-200">
              <span className="text-[10px] font-black text-slate-400 uppercase ml-2">График:</span>
              <input 
                type="datetime-local" 
                value={scheduleDate} 
                onChange={(e) => setScheduleDate(e.target.value)} 
