              <button 
                onClick={() => handlePublish('vk')}
                disabled={!!publishing}
                className="bg-blue-600 text-white text-[10px] font-black py-3 rounded-xl hover:bg-blue-700 disabled:opacity-50 uppercase tracking-widest shadow-lg shadow-blue-100 transition-all"
              >
                {publishing === 'vk' ? '...' : scheduleDate ? 'В ГРАФИК ВК' : 'В ВКОНТАКТЕ'}
              </button>
           </div>
        </div>

        <div className="p-6 flex-1 bg-white">
          {activeView === 'short' ? (
              <div className="space-y-6">
                  <div className="flex items-center gap-2 text-brand-orange font-black text-[10px] uppercase tracking-[0.2em]">
                      <span className="relative flex h-2 w-2">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-brand-orange opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-2 w-2 bg-brand-orange"></span>
                      </span>
                      Эфир: Бегущая строка
                  </div>
