    return parsed;
  } catch (error) {
    throw new Error("Не удалось найти новости.");
  }
};

export const generateCreativeContent = async (newsItem: NewsItem, sarcasmLevel: number): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — РЕДАКЦИЯ "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ". 
    ПИШИ СТРОГО ОТ ЛИЦА РЕДАКЦИИ (ИСПОЛЬЗУЙ "МЫ", "НАШИ ЭКСПЕРТЫ", "МЫ СЧИТАЕМ"). НИКАКИХ "Я".
    СЕГОДНЯ: ${today}.
    УРОВЕНЬ САРКАЗМА И ЮМОРА: ${sarcasmLevel} из 10. (Если 10 — используй едкую сатиру и парадоксы).

    ЗАДАЧА: Написать глубокую статью (2500+ знаков) и посты.

    ТРЕБОВАНИЯ К ТЕКСТУ:
    - БЕЗ РАЗМЕТКИ: Никаких **, ***, #, []. Только чистый, профессионально сверстанный текст.
    - ХЕШТЕГИ: Строго БЕЗ знака #. Просто слова через запятую.
    - ЮМОР: Используй стиль Михаила Жванецкого (парадоксальность) и Иоанны Хмелевской (ироничный детектив).
    - ИЗОБРАЖЕНИЯ: Промпты для ФОТО 16:9, без текста внутри.

    ВЕРНИ JSON:
    {
      "siteArticle": { "headline": "...", "content": "...", "hashtags": "туризм, новости, аналитика" },
      "telegramPost": { "content": "..." },
      "vkPost": { "content": "..." },
      "imagePrompts": ["Cinematic 16:9 wide photo of...", "Professional 16:9 travel photography...", "Detailed 16:9 shot related to..."],
      "metaDescription": "..."
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Новость: ${newsItem.title}. Факты: ${newsItem.summary}. Сарказм: ${sarcasmLevel}/10. Пиши от лица "Первого Туристического". Сделай это остроумно!`,
      config: { systemInstruction, responseMimeType: "application/json" },
    });
    const parsed = robustJSONParse(response.text || "");
    parsed.siteArticle.content = cleanMarkdown(parsed.siteArticle.content) + `\n\nИсточник: ${newsItem.sourceUrl}`;
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    throw new Error(`Ошибка генерации для: ${newsItem.title}`);
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `STRICTLY ASPECT RATIO 16:9. High quality professional wide photography. No text (unless specified). ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) { 
    return ""; 
  }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await delay(2500); 
  }
  while (images.length < 3) images.push("https://placehold.co/1600x900?text=Error");
  return images;
};

import React, { useState, useEffect } from 'react';
import { generateDailyDigest, generateCreativeContent, generateImagesForPack, generateImage } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { NewsCard } from './components/NewsCard';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { AddNewsModal } from './components/AddNewsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [sarcasmLevels, setSarcasmLevels] = useState<Record<string, number>>({});
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isAddNewsOpen, setIsAddNewsOpen] = useState(false);

  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    telegramBotToken: '', telegramChatId: '', vkAccessToken: '', vkOwnerId: '', wpUrl: '', wpUsername: 'admin', wpAppPassword: '' 
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { setPubConfig(prev => ({ ...prev, ...JSON.parse(saved) })); } catch (e) {}
    }
  }, []);

  const handleStartResearch = async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Редакция ищет новости...");
    try {
      const data = await generateDailyDigest();
      setDigest(data);
      setAppState(AppState.SELECTING);
      if (data.collagePrompt) {
          generateImage(data.collagePrompt).then(img => {
             if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
          });
      }
    } catch (e: any) {
      setErrorMsg(e.message);
      setAppState(AppState.ERROR);
    }
  };

  const toggleNewsSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) {
        const newLevels = { ...sarcasmLevels };
        delete newLevels[id];
        setSarcasmLevels(newLevels);
        return prev.filter(i => i !== id);
      }
      if (prev.length >= MAX_SELECTION) return prev;
      setSarcasmLevels(l => ({ ...l, [id]: 5 }));
      return [...prev, id];
    });
  };

  const updateSarcasm = (id: string, val: number) => {
    setSarcasmLevels(prev => ({ ...prev, [id]: val }));
  };

  const handleGenerateContent = async () => {
    if (selectedNewsIds.length === 0) return;
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    // Цикл по всем выбранным новостям
    for (let i = 0; i < selectedItems.length; i++) {
      const item = selectedItems[i];
      const level = sarcasmLevels[item.id] || 5;

      setStatusMessage(`[${i+1}/${selectedItems.length}] Пишем статью: "${item.title.substring(0, 30)}..."`);

      try {
        const content = await generateCreativeContent(item, level);
        setStatusMessage(`[${i+1}/${selectedItems.length}] Рисуем кадры 16:9...`);
        const images = await generateImagesForPack(content.imagePrompts);

        const fullPack = { ...content, generatedImages: images };
        setGeneratedResults(prev => [...prev, fullPack]);
      } catch (err: any) {
        console.error("Failed item:", item.title, err);
      }
    }

    setAppState(AppState.COMPLETED);
  };

  return (
    <div className="min-h-screen bg-[#f5f5f7] pb-10">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />
      <AddNewsModal isOpen={isAddNewsOpen} onClose={() => setIsAddNewsOpen(false)} onAdd={(n) => setDigest(prev => prev ? ({...prev, news:[{...n, id:Date.now().toString()}, ...prev.news]}) : null)} />

      <nav className="bg-brand-dark h-16 flex items-center px-6 sticky top-0 z-50 shadow-xl">
        <h1 className="text-white font-bold uppercase tracking-tighter text-xl italic">ПЕРВЫЙ <span className="text-brand-orange">ТУРИСТИЧЕСКИЙ</span> AI</h1>
        <div className="ml-6 px-3 py-1 bg-brand-orange/20 border border-brand-orange/40 rounded-full text-[10px] text-brand-orange font-black uppercase tracking-widest animate-pulse">
           LIVE ЭФИР
        </div>
        <button onClick={() => setIsSettingsOpen(true)} className="ml-auto p-2 bg-white/10 rounded-full hover:bg-white/20 transition-all text-xl">⚙️</button>
      </nav>

      <main className="max-w-[1440px] mx-auto p-6">
        {appState === AppState.ERROR && (
           <div className="text-center py-20 bg-white rounded-3xl shadow-xl border border-red-100">
              <div className="text-7xl mb-6">🏜️</div>
              <h2 className="text-2xl text-red-500 font-black mb-4 uppercase tracking-tight">Ошибка в эфире</h2>
              <p className="text-slate-400 mb-8">{errorMsg}</p>
              <button onClick={() => setAppState(AppState.IDLE)} className="bg-brand-orange text-white px-10 py-4 rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-orange-200">Перезапустить</button>
           </div>
        )}

        {appState === AppState.IDLE && (
          <div className="flex flex-col items-center py-20 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-brand-orange via-yellow-400 to-brand-orange"></div>
            <div className="w-28 h-28 bg-brand-orange/10 rounded-full flex items-center justify-center mb-10 ring-8 ring-brand-orange/5">
               <span className="text-5xl">📡</span>
            </div>
            <h2 className="text-5xl font-black mb-4 uppercase text-brand-dark tracking-tighter">Редакция на связи</h2>
            <p className="text-slate-500 mb-12 max-w-lg text-center font-medium text-lg leading-relaxed">
               Готовим глубокую аналитику и профессиональный сарказм для вашего контента.
            </p>
            <button onClick={handleStartResearch} className="px-16 py-5 bg-brand-dark text-white font-black rounded-2xl uppercase tracking-[0.2em] hover:bg-brand-orange hover:scale-105 transition-all shadow-2xl shadow-slate-400">Начать поиск новостей</button>
          </div>
        )}

        {(appState === AppState.SEARCHING || appState === AppState.GENERATING_CONTENT) && (
          <div className="flex flex-col items-center py-40">
            <div className="relative mb-12">
                <div className="w-24 h-24 border-[6px] border-brand-orange border-t-transparent rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center font-black text-sm text-brand-orange uppercase">TOUR</div>
            </div>
            <h3 className="text-3xl font-black text-brand-dark tracking-tighter mb-2 uppercase">{statusMessage}</h3>
            <div className="flex gap-1.5">
               <div className="w-2 h-2 bg-brand-orange rounded-full animate-bounce"></div>
               <div className="w-2 h-2 bg-brand-orange rounded-full animate-bounce [animation-delay:0.2s]"></div>
               <div className="w-2 h-2 bg-brand-orange rounded-full animate-bounce [animation-delay:0.4s]"></div>
            </div>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div className="animate-fade-in">
            <div className="flex justify-between items-center mb-10 bg-white/90 p-8 rounded-[2rem] border border-slate-200 backdrop-blur-xl sticky top-20 z-30 shadow-2xl">
               <div>
                  <h2 className="text-3xl font-black uppercase text-brand-dark tracking-tighter">Темы для эфира</h2>
                  <p className="text-xs font-black text-brand-orange uppercase tracking-[0.2em] mt-1">Выберите до {MAX_SELECTION} новостей</p>
               </div>
               <div className="flex gap-4">
                  <button onClick={() => setIsAddNewsOpen(true)} className="px-6 py-3 border-2 border-slate-200 rounded-2xl font-black text-xs uppercase hover:bg-slate-50 transition-all tracking-widest"> + Своя тема </button>
                  <button onClick={handleGenerateContent} disabled={selectedNewsIds.length === 0} className={`px-10 py-3 rounded-2xl font-black text-xs uppercase transition-all tracking-[0.2em] ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white shadow-xl shadow-orange-200 scale-105' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
                    Писать выпуск ({selectedNewsIds.length})
                  </button>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
               {digest.news.map(n => (
                 <NewsCard 
                    key={n.id} 
                    item={n} 
                    isSelected={selectedNewsIds.includes(n.id)} 
                    onToggle={toggleNewsSelection} 
                    onMarkReplace={() => {}} 
                    isMarkedForReplace={false}
                    sarcasmValue={sarcasmLevels[n.id] || 5}
                    onSarcasmChange={(val) => updateSarcasm(n.id, val)}
                 />
               ))}
            </div>
          </div>
        )}

        {appState === AppState.COMPLETED && (
           <div className="space-y-12 animate-fade-in">
              <div className="flex items-center justify-between">
                  <h2 className="text-3xl font-black uppercase text-brand-dark tracking-tighter border-l-8 border-brand-orange pl-6">Готовый выпуск</h2>
                  <button onClick={() => setAppState(AppState.IDLE)} className="px-6 py-2 bg-white rounded-xl border border-slate-200 font-black text-[10px] uppercase text-slate-400 hover:text-brand-orange transition-all">Новый поиск</button>
              </div>
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  <div className="lg:col-span-4 h-full">
                    {digest && <DigestPostViewer digest={digest} pubConfig={pubConfig} />}
                  </div>
                  <div className="lg:col-span-8 space-y-12">
                    {generatedResults.map((res, idx) => (
                      <div key={res.newsId} className="animate-fade-in [animation-delay:0.2s]">
                         <ResultViewer pack={res} pubConfig={pubConfig} />
                      </div>
                    ))}
                  </div>
              </div>
           </div>
        )}
      </main>
    </div>
  );
};

