    - ХЕШТЕГИ: Строго БЕЗ знака #. Просто слова через запятую.
    - ЮМОР: Это должен быть интеллектуальный юмор, ирония над ситуацией, а не просто шутки.
    - ИЗОБРАЖЕНИЯ: Промпты для ФОТОГРАФИЙ 16:9, без текста.

    ВЕРНИ JSON:
    {
      "siteArticle": { "headline": "...", "content": "...", "hashtags": "туризм, новости, рф" },
      "telegramPost": { "content": "..." },
      "vkPost": { "content": "..." },
      "imagePrompts": ["Cinematic 16:9 wide photo of...", "Professional 16:9 travel shot...", "High quality 16:9 detail of..."],
      "metaDescription": "..."
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Сарказм: ${sarcasmLevel}/10. Пиши от имени "Первого Туристического". Сделай это ОЧЕНЬ смешно и профессионально одновременно.`,
      config: { systemInstruction, responseMimeType: "application/json" },
    });
    const parsed = robustJSONParse(response.text || "");
    parsed.siteArticle.content = cleanMarkdown(parsed.siteArticle.content) + `\n\nИсточник: ${newsItem.sourceUrl || 'Редакция'}`;
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    throw new Error(`Ошибка генерации для: ${newsItem.title}`);
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `STRICTLY 16:9 ASPECT RATIO. Wide format travel photography. ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) { 
    console.error("Image Gen Error:", err);
    return ""; 
  }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
