            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-brand-orange via-yellow-400 to-brand-orange"></div>
            <div className="w-32 h-32 bg-brand-orange/10 rounded-full flex items-center justify-center mb-10 ring-8 ring-brand-orange/5">
               <span className="text-6xl">📡</span>
            </div>
