import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const timeout = (ms: number) => new Promise((_, reject) => 
  setTimeout(() => reject(new Error("Превышено время ожидания поиска (тайм-аут). Попробуйте еще раз или используйте ручной ввод.")), ms)
);

const cleanMarkdown = (text: string) => {
    if (!text) return "";
    return text
        .replace(/\*\*\*/g, '')
        .replace(/\*\*/g, '')
        .replace(/\*/g, '')
        .replace(/__/g, '')
        .replace(/#/g, '')
        .replace(/\[|\]/g, '')
        .replace(/<[^>]*>?/gm, '') 
        .replace(/&nbsp;/g, ' ')
        .replace(/\\n/g, '\n')
        .trim();
};

const robustJSONParse = (text: string): any => {
    if (!text) throw new Error("ИИ вернул пустой ответ");
    // Удаляем возможные префиксы типа "json", "markdown" и т.д.
    let cleaned = text.replace(/```[a-z]*\n?/gi, '').replace(/```/g, '').trim();
    try {
        return JSON.parse(cleaned);
    } catch (e) {
        // Попытка найти JSON внутри текста, если модель добавила лишний текст вокруг
        const jsonMatch = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        if (jsonMatch) {
            try {
                return JSON.parse(jsonMatch[0]);
            } catch (e2) {
                throw new Error("Не удалось извлечь корректный JSON из ответа ИИ.");
            }
        }
        throw new Error("Ответ ИИ не содержит структуры JSON.");
    }
};

export const generateDailyDigest = async (globalSarcasm: number = 5): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". СТИЛЬ: "МЫ" (РЕДАКЦИЯ).
    ЗАДАЧА: Найти 10 свежих новостей туризма в РФ (последние 24-48ч).

    ФОРМАТ ОТВЕТА (JSON):
    - formattedDigestText: Текст с эмодзи в начале каждой новости. Стиль "Мы".
    - formattedShortDigest: Формат "ЭМОДЗИ Новость — Краткий комментарий".
    - news: Массив объектов с title, summary, location, sourceUrl, date.
    - collagePrompt: Промпт для обложки 16:9 с текстом "НОВОСТИ ТУРИЗМА".

    ВЕРНИ ТОЛЬКО ЧИСТЫЙ JSON.
  `;

  const searchCall = ai.models.generateContent({
    model,
    contents: `Собери 10 главных новостей туризма в России на ${today}. Используй поиск. Уровень иронии: ${globalSarcasm}/10. Говори от имени "Первого Туристического".`,
    config: { 
      tools: [{ googleSearch: {} }], 
      systemInstruction,
      // Убираем жесткий responseMimeType для поиска, так как это иногда вызывает зависания в связке с инструментами
    },
  });

  try {
    // Ждем либо ответа, либо 50 секунд (поиск может быть долгим)
    const response = await Promise.race([searchCall, timeout(50000)]) as any;
    const parsed = robustJSONParse(response.text || "");

    if (!parsed.news || parsed.news.length === 0) {
        throw new Error("Новости не найдены. Попробуйте сменить запрос или добавить тему вручную.");
    }

    parsed.news = (parsed.news || []).map((n: any, i: number) => ({ ...n, id: `n-${i}-${Date.now()}` }));
    return parsed;
  } catch (error: any) {
    console.error("Digest error:", error);
    throw new Error(error.message || "Ошибка соединения с ИИ. Возможно, инструмент поиска ограничен в вашем регионе.");
  }
};

export const generateCreativeContent = async (newsItem: NewsItem, sarcasmLevel: number): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — РЕДАКЦИЯ "ПЕРВОГО ТУРИСТИЧЕСКОГО". ПИШИ "МЫ". НИКАКИХ "Я".
    ЗАДАЧА: Написать статью (2500+ знаков) и посты для соцсетей.

    ТРЕБОВАНИЯ:
    - ЧИСТЫЙ ТЕКСТ (без **, #, []).
    - ХЕШТЕГИ: Без #, через запятую.
    - КАРТИНКИ: Промпты для 16:9.
    - УРОВЕНЬ САРКАЗМА: ${sarcasmLevel}/10.

    ОТВЕТЬ В JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Сарказм: ${sarcasmLevel}/10. Пиши от лица "Первого Туристического".`,
      config: { systemInstruction, responseMimeType: "application/json" },
    });
    const parsed = robustJSONParse(response.text || "");
    parsed.siteArticle.content = cleanMarkdown(parsed.siteArticle.content) + `\n\nИсточник: ${newsItem.sourceUrl || 'Редакция'}`;
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    throw new Error(`Ошибка генерации для: ${newsItem.title}`);
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Professional wide shot, 16:9 aspect ratio, cinematic quality. ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) { 
    return ""; 
  }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await delay(1200); 
  }
  while (images.length < 3) images.push("https://placehold.co/1600x900?text=Generation+Error");
  return images;
};

