import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const timeout = (ms: number, message: string) => new Promise((_, reject) => 
  setTimeout(() => reject(new Error(message)), ms)
);

const cleanMarkdown = (text: string) => {
    if (!text) return "";
    return text
        .replace(/\*\*\*/g, '')
        .replace(/\*\*/g, '')
        .replace(/\*/g, '')
        .replace(/__/g, '')
        .replace(/#/g, '')
        .replace(/\[|\]/g, '')
        .replace(/<[^>]*>?/gm, '') 
        .replace(/&nbsp;/g, ' ')
        .replace(/\\n/g, '\n')
        .trim();
};

const robustJSONParse = (text: string): any => {
    if (!text) throw new Error("ИИ вернул пустой ответ");
    let cleaned = text.replace(/```[a-z]*\n?/gi, '').replace(/```/g, '').trim();
    try {
        return JSON.parse(cleaned);
    } catch (e) {
        const jsonMatch = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        if (jsonMatch) {
            try {
                return JSON.parse(jsonMatch[0]);
            } catch (e2) {
                throw new Error("Не удалось извлечь структуру JSON.");
            }
        }
        throw new Error("Ответ ИИ не является корректным JSON.");
    }
};

export const generateDailyDigest = async (globalSarcasm: number = 5): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". СТИЛЬ: "МЫ" (РЕДАКЦИЯ).
    ЗАДАЧА: Сформировать 10 свежих новостей туризма в РФ (последние 24-48ч).

    ОБЯЗАТЕЛЬНЫЙ ФОРМАТ ОТВЕТА (JSON):
    {
      "news": [{ "title": "...", "summary": "...", "location": "...", "sourceUrl": "...", "date": "..." }],
      "hacks": ["..."],
      "facts": ["..."],
      "formattedDigestText": "Текст дайджеста с эмодзи в начале каждой новости...",
      "formattedShortDigest": "🚩 Новость — Краткий ироничный комментарий...",
      "collagePrompt": "Промпт для обложки 16:9 с текстом 'НОВОСТИ ТУРИЗМА'"
    }

    ВЕРНИ ТОЛЬКО ЧИСТЫЙ JSON. БЕЗ ЛИШНЕГО ТЕКСТА.
  `;

  const prompt = `Собери 10 актуальных новостей туризма в России на ${today}. Уровень иронии: ${globalSarcasm}/10. Говори от имени редакции "Первый Туристический".`;

  try {
    console.log("Attempting search-enabled generation...");
    // Первая попытка: с использованием поиска
    const searchCall = ai.models.generateContent({
      model,
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }], 
        systemInstruction,
      },
    });

    const response = await Promise.race([
        searchCall, 
        timeout(45000, "Google Search не ответил вовремя. Пробуем альтернативный метод...")
    ]) as any;

    return robustJSONParse(response.text || "");

  } catch (error: any) {
    console.warn("Search attempt failed or timed out, trying fallback without tools:", error.message);

    // Вторая попытка (Фолбэк): без инструментов поиска (если они заблокированы в регионе)
    try {
      const fallbackCall = ai.models.generateContent({
        model: "gemini-3-pro-preview", // Используем более умную модель для фолбэка
        contents: `${prompt} (Примечание: Поиск сейчас недоступен, используй свои внутренние знания о самых свежих трендах начала 2025 года).`,
        config: { 
          systemInstruction,
          responseMimeType: "application/json"
        },
      });

      const fallbackResponse = await Promise.race([
          fallbackCall, 
          timeout(30000, "Сервер ИИ перегружен. Пожалуйста, попробуйте еще раз позже.")
      ]) as any;

      const parsed = robustJSONParse(fallbackResponse.text || "");
      if (!parsed.news || parsed.news.length === 0) throw new Error("Не удалось получить список новостей.");

      parsed.news = parsed.news.map((n: any, i: number) => ({ ...n, id: `n-${i}-${Date.now()}` }));
      return parsed;

    } catch (fallbackError: any) {
      throw new Error("Не удалось выполнить поиск. Вероятно, сервис Google Search заблокирован в вашей стране. Пожалуйста, добавьте новость вручную.");
    }
  }
};

export const generateCreativeContent = async (newsItem: NewsItem, sarcasmLevel: number): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — РЕДАКЦИЯ "ПЕРВОГО ТУРИСТИЧЕСКОГО". ПИШИ "МЫ".
    ЗАДАЧА: Написать статью (2500+ знаков) и посты.
    ТРЕБОВАНИЯ: Чистый текст, хештеги без #, промпты 16:9.
    ВЕРНИ JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Сарказм: ${sarcasmLevel}/10.`,
      config: { systemInstruction, responseMimeType: "application/json" },
    });
    const parsed = robustJSONParse(response.text || "");
    parsed.siteArticle.content = cleanMarkdown(parsed.siteArticle.content) + `\n\nИсточник: ${newsItem.sourceUrl || 'Редакция'}`;
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    throw new Error(`Ошибка генерации для: ${newsItem.title}`);
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Professional wide 16:9 photography. ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) { 
    return ""; 
  }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await delay(1000); 
  }
  while (images.length < 3) images.push("https://placehold.co/1600x900?text=Generation+Error");
  return images;
};

