import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const robustJSONParse = (text: string): any => {
    if (!text) throw new Error("Пустой ответ от редакции.");
    let cleaned = text.replace(/```[a-z]*\n?/gi, '').replace(/```/g, '').trim();
    try {
        return JSON.parse(cleaned);
    } catch (e) {
        const jsonMatch = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        if (jsonMatch) {
            try { return JSON.parse(jsonMatch[0]); } catch (e2) { throw new Error("Ошибка структуры данных."); }
        }
        throw new Error("Некорректный формат ответа ИИ.");
    }
};

export const generateDailyDigest = async (globalSarcasm: number = 5): Promise<DigestData> => {
  const today = getCurrentDate();
  const searchModel = "gemini-3-flash-preview";
  const fallbackModel = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". СТИЛЬ: "МЫ".
    ЗАДАЧА: Сформировать выпуск из 10 новостей туризма в РФ (последние 48ч).

    JSON ФОРМАТ:
    {
      "news": [{ "title": "...", "summary": "...", "location": "...", "sourceUrl": "...", "date": "..." }],
      "hacks": ["..."],
      "facts": ["..."],
      "formattedDigestText": "Текст от 'Мы' с эмодзи...",
      "formattedShortDigest": "🚩 Новость — Комментарий...",
      "collagePrompt": "Wide 16:9 travel collage with Russian text 'НОВОСТИ ТУРИЗМА'"
    }
  `;

  // Пытаемся выполнить поиск
  try {
    const response = await ai.models.generateContent({
      model: searchModel,
      contents: `Найди и собери 10 главных новостей туризма в России на ${today}. Сарказм: ${globalSarcasm}/10. Говори от имени "Первого Туристического".`,
      config: { 
        tools: [{ googleSearch: {} }], 
        systemInstruction,
        temperature: 0.7
      },
    });

    const data = robustJSONParse(response.text || "");
    if (!data.news || data.news.length === 0) throw new Error("Поиск не дал результатов.");
    return data;

  } catch (error: any) {
    console.warn("Основной поиск заблокирован или недоступен в данном регионе. Переход на интеллектуальный синтез...", error.message);

    // Фолбэк: если Google Search в Турции блокируется, используем знания модели Gemini 3 Pro
    try {
      const fallbackResponse = await ai.models.generateContent({
        model: fallbackModel,
        contents: `ВНИМАНИЕ: Поиск временно недоступен. Сгенерируй актуальный дайджест из 10 ГЛАВНЫХ ТРЕНДОВ И СОБЫТИЙ туризма в России на ${today}, основываясь на текущей ситуации (начало 2025 года). Пиши от лица "Первого Туристического" (МЫ). Сарказм: ${globalSarcasm}/10.`,
        config: { 
          systemInstruction,
          responseMimeType: "application/json"
        },
      });

      const data = robustJSONParse(fallbackResponse.text || "");
      data.news = (data.news || []).map((n: any, i: number) => ({ ...n, id: `synth-${i}-${Date.now()}` }));
      return data;
    } catch (fError) {
      throw new Error("Критический сбой связи. Пожалуйста, проверьте VPN или добавьте новость вручную.");
    }
  }
};

export const generateCreativeContent = async (newsItem: NewsItem, sarcasmLevel: number): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — РЕДАКЦИЯ "ПЕРВОГО ТУРИСТИЧЕСКОГО". СТИЛЬ: "МЫ".
    ЗАДАЧА: Написать статью (2500+ знаков) и посты.
    ТРЕБОВАНИЯ: Чистый текст, хештеги без #, все картинки 16:9.
    ОТВЕТЬ В JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Сарказм: ${sarcasmLevel}/10. Пиши от лица "Первого Туристического".`,
      config: { systemInstruction, responseMimeType: "application/json" },
    });
    return { newsId: newsItem.id, ...robustJSONParse(response.text || "") };
  } catch (error) {
    throw new Error(`Ошибка генерации контента для: ${newsItem.title}`);
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Professional wide shot, 16:9 aspect ratio, high resolution, cinematic travel photography. ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) { return ""; }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
      const img = await generateImage(p);
      if (img) images.push(img);
      await delay(1000);
  }
  while (images.length < 3) images.push("https://placehold.co/1600x900?text=Generation+Error");
  return images;
};

