import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [sarcasmLevels, setSarcasmLevels] = useState<Record<string, number>>({});
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isAddNewsOpen, setIsAddNewsOpen] = useState(false);

  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    telegramBotToken: '', telegramChatId: '', vkAccessToken: '', vkOwnerId: '', wpUrl: '', wpUsername: 'admin', wpAppPassword: '' 
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { setPubConfig(prev => ({ ...prev, ...JSON.parse(saved) })); } catch (e) {}
    }
  }, []);

  const handleStartResearch = async () => {
    setAppState(AppState.SEARCHING);
    setGeneratedResults([]);
    setSelectedNewsIds([]);
    setErrorMsg('');
    setStatusMessage("Подключение к глобальной сети...");

    // Мониторинг времени
    const statusTimer = setTimeout(() => {
        setStatusMessage("Сеть замедлена. Переходим на синтез данных...");
    }, 12000);

    try {
      const data = await generateDailyDigest();
      clearTimeout(statusTimer);
      setDigest(data);
      setAppState(AppState.SELECTING);
      if (data.collagePrompt) {
          generateImage(data.collagePrompt).then(img => {
             if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
          });
      }
    } catch (e: any) {
      clearTimeout(statusTimer);
      console.error("Research failed:", e);
      setErrorMsg(e.message || "Ошибка соединения. В Турции рекомендуется использовать VPN для стабильного поиска.");
      setAppState(AppState.ERROR);
    }
  };

  const toggleNewsSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) {
        const newLevels = { ...sarcasmLevels };
        delete newLevels[id];
        setSarcasmLevels(newLevels);
        return prev.filter(i => i !== id);
      }
      if (prev.length >= MAX_SELECTION) return prev;
      setSarcasmLevels(l => ({ ...l, [id]: 5 }));
      return [...prev, id];
    });
  };

  const updateSarcasm = (id: string, val: number) => {
    setSarcasmLevels(prev => ({ ...prev, [id]: val }));
  };

  const handleGenerateContent = async () => {
    if (selectedNewsIds.length === 0) return;
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < selectedItems.length; i++) {
      const item = selectedItems[i];
      const level = sarcasmLevels[item.id] || 5;

      setStatusMessage(`[${i+1}/${selectedItems.length}] Пишем статью: ${item.title.substring(0, 30)}...`);

      try {
        const content = await generateCreativeContent(item, level);
        setStatusMessage(`[${i+1}/${selectedItems.length}] Создаем кадры 16:9...`);
        const images = await generateImagesForPack(content.imagePrompts);

        const fullPack = { ...content, generatedImages: images };
        setGeneratedResults(prev => [...prev, fullPack]);
      } catch (err: any) {
        console.error("Generation error:", err);
        setGeneratedResults(prev => [...prev, { 
          newsId: item.id,
          siteArticle: { headline: 'Сбой редакции', content: `Не удалось написать текст для: ${item.title}.`, hashtags: '' },
          telegramPost: { content: '' },
          vkPost: { content: '' },
          imagePrompts: [],
          metaDescription: '',
          generatedImages: ["https://placehold.co/1600x900?text=Error"],
          error: err.message
        }]);
      }
    }

    setAppState(AppState.COMPLETED);
  };

  const todayDisplay = new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });

  return (
    <div className="min-h-screen bg-[#f5f5f7] pb-10">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />
      <AddNewsModal isOpen={isAddNewsOpen} onClose={() => setIsAddNewsOpen(false)} onAdd={(n) => {
        const newItem = {...n, id: Date.now().toString()};
        setDigest(prev => {
          const base = prev || { news: [], hacks: [], facts: [], formattedDigestText: '', formattedShortDigest: '', collagePrompt: '' };
          return {...base, news:[newItem, ...base.news]};
        });
        setAppState(AppState.SELECTING);
      }} />

      <nav className="bg-brand-dark h-16 flex items-center px-6 sticky top-0 z-50 shadow-2xl">
        <h1 className="text-white font-bold uppercase tracking-tighter text-xl italic">ПЕРВЫЙ <span className="text-brand-orange">ТУРИСТИЧЕСКИЙ</span> AI</h1>
        <div className="ml-6 px-3 py-1 bg-brand-orange/20 border border-brand-orange/40 rounded-full text-[10px] text-brand-orange font-black uppercase tracking-widest animate-pulse">
           {todayDisplay} • LIVE (GLOBAL)
        </div>
        <button onClick={() => setIsSettingsOpen(true)} className="ml-auto p-2 bg-white/10 rounded-full hover:bg-white/20 transition-all text-xl">⚙️</button>
      </nav>

      <main className="max-w-[1440px] mx-auto p-6">
        {appState === AppState.ERROR && (
           <div className="text-center py-16 bg-white rounded-[2rem] shadow-xl border border-red-100 animate-fade-in max-w-2xl mx-auto">
              <div className="text-7xl mb-6">🏜️</div>
              <h2 className="text-2xl text-red-500 font-black mb-4 uppercase tracking-tight">Эфир прерван</h2>
              <p className="text-slate-500 mb-8 px-10 leading-relaxed font-medium">{errorMsg}</p>
              <div className="flex flex-col sm:flex-row justify-center gap-4 px-10">
                  <button onClick={handleStartResearch} className="bg-brand-orange text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-orange-200 hover:scale-105 transition-all">Повторить</button>
                  <button onClick={() => setIsAddNewsOpen(true)} className="bg-slate-800 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest hover:bg-black transition-all">Ручной ввод темы</button>
              </div>
           </div>
        )}

        {appState === AppState.IDLE && (
          <div className="flex flex-col items-center py-24 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 relative overflow-hidden animate-fade-in">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-brand-orange via-yellow-400 to-brand-orange"></div>
            <div className="w-32 h-32 bg-brand-orange/10 rounded-full flex items-center justify-center mb-10 ring-8 ring-brand-orange/5">
               <span className="text-6xl">🌍</span>
            </div>
            <h2 className="text-5xl font-black mb-4 uppercase text-brand-dark tracking-tighter text-center italic">Пульт Редакции</h2>
            <p className="text-slate-500 mb-12 max-w-xl text-center font-medium text-lg leading-relaxed px-6">
               Интеллектуальный сбор новостей с защитой от сбоев. Если поиск в Турции будет заблокирован, мы создадим выпуск на основе аналитики.
            </p>
            <div className="flex flex-col sm:flex-row gap-4">
                <button onClick={handleStartResearch} className="px-16 py-6 bg-brand-dark text-white font-black rounded-2xl uppercase tracking-[0.2em] hover:bg-brand-orange hover:scale-105 transition-all shadow-2xl shadow-slate-400">Начать выпуск</button>
                <button onClick={() => setIsAddNewsOpen(true)} className="px-10 py-6 bg-white border-2 border-slate-200 text-brand-dark font-black rounded-2xl uppercase tracking-[0.1em] hover:border-brand-orange transition-all">Своя тема</button>
            </div>
          </div>
        )}

        {appState === AppState.SEARCHING && (
          <div className="flex flex-col items-center py-48">
            <div className="relative mb-12">
                <div className="w-24 h-24 border-[6px] border-brand-orange border-t-transparent rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center font-black text-sm text-brand-orange uppercase">AI</div>
            </div>
            <h3 className="text-3xl font-black text-brand-dark tracking-tighter mb-2 uppercase text-center italic">{statusMessage}</h3>
            <p className="text-slate-400 animate-pulse font-bold text-xs uppercase tracking-widest mt-4">Ищем лучшие инфоповоды по всему миру...</p>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div className="animate-fade-in">
            <div className="flex flex-col md:flex-row justify-between items-center mb-10 bg-white/90 p-8 rounded-[2.5rem] border border-slate-200 backdrop-blur-xl sticky top-20 z-30 shadow-2xl gap-6">
               <div>
                  <h2 className="text-3xl font-black uppercase text-brand-dark tracking-tighter">Сводка событий</h2>
                  <p className="text-xs font-black text-brand-orange uppercase tracking-[0.2em] mt-1">Выберите 2 новости для глубокой аналитики</p>
               </div>
               <div className="flex gap-4">
                  <button onClick={() => setIsAddNewsOpen(true)} className="px-6 py-3 border-2 border-slate-200 rounded-2xl font-black text-xs uppercase hover:bg-slate-50 transition-all tracking-widest"> + Своя тема </button>
                  <button onClick={handleGenerateContent} disabled={selectedNewsIds.length === 0} className={`px-10 py-3 rounded-2xl font-black text-xs uppercase transition-all tracking-[0.2em] ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white shadow-xl shadow-orange-200 scale-105' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
                    Писать статьи ({selectedNewsIds.length})
                  </button>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 pb-20">
               {digest.news.map(n => (
                 <NewsCard 
                    key={n.id} 
                    item={n} 
                    isSelected={selectedNewsIds.includes(n.id)} 
                    onToggle={toggleNewsSelection} 
                    onMarkReplace={() => {}} 
                    isMarkedForReplace={false}
                    sarcasmValue={sarcasmLevels[n.id] || 5}
                    onSarcasmChange={(val) => updateSarcasm(n.id, val)}
                 />
               ))}
            </div>
          </div>
        )}

        {(appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && (
           <div className="space-y-12 animate-fade-in">
              <div className="flex items-center justify-between bg-white/50 p-6 rounded-3xl backdrop-blur-sm border border-white/50">
