                  </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  <div className="lg:col-span-4 h-full sticky top-32">
                    {digest && (digest.formattedDigestText || digest.news.length > 0) && <DigestPostViewer digest={digest} pubConfig={pubConfig} />}
                  </div>
                  <div className="lg:col-span-8 space-y-12 pb-20">
                    {generatedResults.length === 0 && appState === AppState.GENERATING_CONTENT && (
                       <div className="flex flex-col items-center justify-center py-40 bg-white/30 rounded-[3rem] border-4 border-dashed border-slate-200">
                          <div className="w-16 h-16 border-4 border-slate-200 border-t-brand-orange rounded-full animate-spin mb-6"></div>
                          <p className="text-slate-400 font-black uppercase tracking-widest text-sm text-center px-10">Тщательно прорабатываем фактуру и финансовый анализ...</p>
                       </div>
                    )}
                    {generatedResults.map((res) => (
                      <div key={res.newsId} className="animate-fade-in">
                         <ResultViewer pack={res} pubConfig={pubConfig} />
                      </div>
                    ))}
                  </div>
              </div>
           </div>
        )}
      </main>
    </div>
  );
};

