export const processManualNewsIntoDigest = async (rawNews: {title: string, summary: string}[], globalSarcasm: number = 5): Promise<DigestData> => {
    const today = getCurrentDate();
    const model = "gemini-3-pro-preview";

    const prompt = `
      Обработай следующие 10 новостей для выпуска за ${today}. 
      Уровень иронии: ${globalSarcasm}/10. 
      Напиши общий дайджест для соцсетей и бегущую строку (ироничные краткие факты).

      НОВОСТИ:
      ${rawNews.map((n, i) => `${i+1}. ${n.title}: ${n.summary}`).join('\n')}
    `;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: { systemInstruction: SYSTEM_PROMPT, responseMimeType: "application/json" }
        });
        const data = robustJSONParse(response.text || "");
        // Сохраняем оригинальные данные, если ИИ их изменил
        data.news = rawNews.map((n, i) => ({
            id: `manual-${i}-${Date.now()}`,
            title: n.title,
            summary: n.summary,
            location: 'РФ'
        }));
        return data;
    } catch (error) {
        throw new Error("Ошибка обработки редакционного материала.");
    }
};

export const generateDailyDigest = async (globalSarcasm: number = 5): Promise<DigestData> => {
