  }
`;

export const processRawTextIntoDigest = async (rawText: string, globalSarcasm: number = 5): Promise<DigestData> => {
    const today = getCurrentDate();
    const model = "gemini-3-pro-preview";

    const prompt = `
      РАЗБЕРИ СЛЕДУЮЩИЙ ТЕКСТ ДЛЯ ВЫПУСКА ЗА ${today}. 
      Уровень иронии: ${globalSarcasm}/10. 

      ТЕКСТ НОВОСТЕЙ:
      ${rawText}
    `;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: { 
                systemInstruction: SYSTEM_PROMPT, 
                responseMimeType: "application/json" 
            }
        });
        const data = robustJSONParse(response.text || "");

        // Гарантируем наличие ID
        data.news = (data.news || []).map((n: any, i: number) => ({
            ...n,
            id: n.id || `raw-${i}-${Date.now()}`
        }));

        return data;
    } catch (error) {
        console.error("Parsing error:", error);
        throw new Error("Не удалось разобрать текст. Попробуйте скопировать новости более четко.");
    }
};

