import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [sarcasmLevels, setSarcasmLevels] = useState<Record<string, number>>({});
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  // Single Window Input
  const [rawText, setRawText] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    telegramBotToken: '', telegramChatId: '', vkAccessToken: '', vkOwnerId: '', wpUrl: '', wpUsername: 'admin', wpAppPassword: '' 
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { setPubConfig(prev => ({ ...prev, ...JSON.parse(saved) })); } catch (e) {}
    }
  }, []);

  const handleStartManualBatch = () => {
      setAppState(AppState.MANUAL_BATCH);
  };

  const handleProcessRawText = async () => {
    if (!rawText.trim() || rawText.length < 50) {
        alert("Пожалуйста, вставьте более подробный текст новостей.");
        return;
    }

    setAppState(AppState.PROCESSING_MANUAL);
    setStatusMessage("Разбираем эфир и формируем ленту...");

    try {
        const data = await processRawTextIntoDigest(rawText);
        setDigest(data);
        setAppState(AppState.SELECTING);
        if (data.collagePrompt) {
            generateImage(data.collagePrompt).then(img => {
               if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
            });
        }
    } catch (e: any) {
        setErrorMsg(e.message || "Ошибка обработки. Проверьте VPN.");
        setAppState(AppState.ERROR);
    }
  };

  const handleStartSearch = async () => {
    setAppState(AppState.SEARCHING);
    setGeneratedResults([]);
    setSelectedNewsIds([]);
    setErrorMsg('');
    setStatusMessage("Поиск в глобальной сети...");

    try {
      const data = await generateDailyDigest();
      setDigest(data);
      setAppState(AppState.SELECTING);
      if (data.collagePrompt) {
          generateImage(data.collagePrompt).then(img => {
             if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
          });
      }
    } catch (e: any) {
      setErrorMsg("В Турции поиск Google может блокироваться. Рекомендуем ручной ввод текста.");
      setAppState(AppState.ERROR);
    }
  };

  const toggleNewsSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) {
        const newLevels = { ...sarcasmLevels };
        delete newLevels[id];
        setSarcasmLevels(newLevels);
        return prev.filter(i => i !== id);
      }
      if (prev.length >= MAX_SELECTION) return prev;
      setSarcasmLevels(l => ({ ...l, [id]: 5 }));
      return [...prev, id];
    });
  };

  const updateSarcasm = (id: string, val: number) => {
    setSarcasmLevels(prev => ({ ...prev, [id]: val }));
  };

  const handleGenerateContent = async () => {
    if (selectedNewsIds.length === 0) return;
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < selectedItems.length; i++) {
      const item = selectedItems[i];
      const level = sarcasmLevels[item.id] || 5;

      setStatusMessage(`[${i+1}/${selectedItems.length}] Пишем статью: ${item.title.substring(0, 30)}...`);

      try {
        const content = await generateCreativeContent(item, level);
        setStatusMessage(`[${i+1}/${selectedItems.length}] Кадры 16:9...`);
        const images = await generateImagesForPack(content.imagePrompts);
        setGeneratedResults(prev => [...prev, { ...content, generatedImages: images }]);
      } catch (err: any) {
        console.error(err);
      }
    }
    setAppState(AppState.COMPLETED);
  };

  const todayDisplay = new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });

  return (
    <div className="min-h-screen bg-[#f5f5f7] pb-10">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />

      <nav className="bg-brand-dark h-16 flex items-center px-6 sticky top-0 z-50 shadow-2xl">
        <h1 className="text-white font-bold uppercase tracking-tighter text-xl italic">ПЕРВЫЙ <span className="text-brand-orange">ТУРИСТИЧЕСКИЙ</span> AI</h1>
        <div className="ml-6 px-3 py-1 bg-brand-orange/20 border border-brand-orange/40 rounded-full text-[10px] text-brand-orange font-black uppercase tracking-widest animate-pulse">
           {todayDisplay} • РЕДАКЦИЯ
        </div>
        <button onClick={() => setIsSettingsOpen(true)} className="ml-auto p-2 bg-white/10 rounded-full hover:bg-white/20 transition-all text-xl">⚙️</button>
      </nav>

      <main className="max-w-[1440px] mx-auto p-6">
        {appState === AppState.IDLE && (
          <div className="flex flex-col items-center py-24 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 relative overflow-hidden animate-fade-in">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-brand-orange via-yellow-400 to-brand-orange"></div>
            <div className="w-32 h-32 bg-brand-orange/10 rounded-full flex items-center justify-center mb-10 ring-8 ring-brand-orange/5">
               <span className="text-6xl">📝</span>
            </div>
            <h2 className="text-5xl font-black mb-4 uppercase text-brand-dark tracking-tighter text-center italic">Пульт Выпуска</h2>
            <p className="text-slate-500 mb-12 max-w-xl text-center font-medium text-lg leading-relaxed px-6">
               Скопируйте все новости дня в одно окно. Наш AI разберет их на части, создаст дайджест и подготовит аналитику.
            </p>
            <div className="flex flex-col sm:flex-row gap-4">
                <button onClick={handleStartManualBatch} className="px-16 py-6 bg-brand-dark text-white font-black rounded-2xl uppercase tracking-[0.2em] hover:bg-brand-orange hover:scale-105 transition-all shadow-2xl shadow-slate-400">Вставить текст выпуска</button>
                <button onClick={handleStartSearch} className="px-10 py-6 bg-white border-2 border-slate-200 text-brand-dark font-black rounded-2xl uppercase tracking-[0.1em] hover:border-brand-orange transition-all">Авто-поиск новостей</button>
            </div>
          </div>
        )}

        {appState === AppState.MANUAL_BATCH && (
            <div className="animate-fade-in bg-white rounded-[2rem] shadow-2xl p-10 border border-slate-100 flex flex-col h-[70vh]">
                <div className="flex justify-between items-center mb-8 shrink-0">
                    <div>
                        <h2 className="text-3xl font-black uppercase text-brand-dark tracking-tighter italic">Единое окно ввода</h2>
                        <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">Просто вставьте весь текст с новостями ниже</p>
                    </div>
                    <div className="flex gap-4">
                        <button onClick={() => setAppState(AppState.IDLE)} className="px-6 py-3 border border-slate-200 rounded-xl font-bold text-xs uppercase text-slate-400">Назад</button>
                        <button onClick={handleProcessRawText} className="px-10 py-4 bg-brand-orange text-white font-black rounded-xl uppercase tracking-widest shadow-xl shadow-orange-200 hover:scale-105 transition-all">Разведать обстановку</button>
                    </div>
                </div>

                <textarea 
                    autoFocus
                    value={rawText}
                    onChange={(e) => setRawText(e.target.value)}
                    placeholder="Вставьте сюда новости (списком, текстом, ссылками)... Рекомендуемый объем: от 500 знаков."
                    className="flex-1 w-full bg-slate-50 rounded-3xl border-2 border-slate-100 p-8 text-lg font-medium outline-none focus:border-brand-orange transition-all custom-scrollbar resize-none"
                />

                <div className="mt-6 flex items-center justify-between text-[10px] font-black text-slate-300 uppercase tracking-widest">
                    <span>Символов: {rawText.length}</span>
                    <span>AI Pro Mode Active</span>
                </div>
            </div>
        )}

        {(appState === AppState.SEARCHING || appState === AppState.PROCESSING_MANUAL) && (
          <div className="flex flex-col items-center py-48">
            <div className="relative mb-12">
                <div className="w-24 h-24 border-[6px] border-brand-orange border-t-transparent rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center font-black text-sm text-brand-orange uppercase">AI</div>
            </div>
            <h3 className="text-3xl font-black text-brand-dark tracking-tighter mb-2 uppercase text-center italic">{statusMessage}</h3>
            <p className="text-slate-400 animate-pulse font-bold text-xs uppercase tracking-widest mt-4">Редакция обрабатывает ваш материал...</p>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div className="animate-fade-in">
            <div className="flex flex-col md:flex-row justify-between items-center mb-10 bg-white/90 p-8 rounded-[2.5rem] border border-slate-200 backdrop-blur-xl sticky top-20 z-30 shadow-2xl gap-6">
               <div>
                  <h2 className="text-3xl font-black uppercase text-brand-dark tracking-tighter italic">Эфирная сетка готова</h2>
                  <p className="text-xs font-black text-brand-orange uppercase tracking-[0.2em] mt-1">Выберите 2 темы для больших статей</p>
               </div>
               <div className="flex gap-4">
                  <button onClick={handleGenerateContent} disabled={selectedNewsIds.length === 0} className={`px-10 py-3 rounded-2xl font-black text-xs uppercase transition-all tracking-[0.2em] ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white shadow-xl shadow-orange-200 scale-105' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
                    Писать статьи ({selectedNewsIds.length})
                  </button>
               </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4 h-full sticky top-32">
                    <DigestPostViewer digest={digest} pubConfig={pubConfig} />
                </div>
                <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-8 pb-20">
                    {digest.news.map(n => (
                        <NewsCard 
                            key={n.id} 
                            item={n} 
                            isSelected={selectedNewsIds.includes(n.id)} 
                            onToggle={toggleNewsSelection} 
                            onMarkReplace={() => {}} 
                            isMarkedForReplace={false}
                            sarcasmValue={sarcasmLevels[n.id] || 5}
                            onSarcasmChange={(val) => updateSarcasm(n.id, val)}
                        />
                    ))}
                    {digest.news.length === 0 && (
                        <div className="col-span-full py-20 text-center border-4 border-dashed border-slate-100 rounded-3xl">
                            <p className="text-slate-300 font-black uppercase tracking-widest">Новости не распознаны. Попробуйте другой текст.</p>
                        </div>
                    )}
                </div>
            </div>
          </div>
        )}

        {(appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && (
           <div className="space-y-12 animate-fade-in">
              <div className="flex items-center justify-between bg-white/50 p-6 rounded-3xl backdrop-blur-sm border border-white/50">
                  <h2 className="text-3xl font-black uppercase text-brand-dark tracking-tighter border-l-8 border-brand-orange pl-6 italic">
                    {appState === AppState.GENERATING_CONTENT ? 'Редакция пишет статьи...' : 'Выпуск завершен'}
                  </h2>
                  <div className="flex gap-4">
                     {appState === AppState.GENERATING_CONTENT && (
                        <div className="flex items-center gap-3 bg-brand-orange/10 px-4 py-2 rounded-xl text-brand-orange font-black text-xs uppercase animate-pulse">
                           <div className="w-2 h-2 bg-brand-orange rounded-full animate-ping"></div>
                           {statusMessage}
                        </div>
                     )}
                     <button onClick={() => setAppState(AppState.IDLE)} className="px-6 py-2 bg-white rounded-xl border border-slate-200 font-black text-[10px] uppercase text-slate-400 hover:text-brand-orange transition-all">Новый выпуск</button>
                  </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  <div className="lg:col-span-4 h-full sticky top-32">
                    {digest && <DigestPostViewer digest={digest} pubConfig={pubConfig} />}
                  </div>
                  <div className="lg:col-span-8 space-y-12 pb-20">
                    {generatedResults.map((res) => (
                      <div key={res.newsId} className="animate-fade-in">
                         <ResultViewer pack={res} pubConfig={pubConfig} />
                      </div>
                    ))}
                  </div>
              </div>
           </div>
        )}

        {appState === AppState.ERROR && (
           <div className="text-center py-16 bg-white rounded-[2rem] shadow-xl border border-red-100 animate-fade-in max-w-2xl mx-auto">
              <div className="text-7xl mb-6">🏜️</div>
              <h2 className="text-2xl text-red-500 font-black mb-4 uppercase tracking-tight">Ошибка в эфире</h2>
              <p className="text-slate-500 mb-8 px-10 leading-relaxed font-medium">{errorMsg}</p>
              <button onClick={() => setAppState(AppState.IDLE)} className="bg-brand-orange text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-orange-200 hover:scale-105 transition-all">Вернуться в начало</button>
           </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const robustJSONParse = (text: string): any => {
    if (!text) throw new Error("Пустой ответ от редакции.");
    // Очистка от markdown-оберток
    let cleaned = text.replace(/```[a-z]*\n?/gi, '').replace(/```/g, '').trim();
    try {
        return JSON.parse(cleaned);
    } catch (e) {
        // Попытка найти JSON внутри текста, если модель добавила комментарии
        const jsonMatch = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        if (jsonMatch) {
            try { return JSON.parse(jsonMatch[0]); } catch (e2) { throw new Error("Ошибка структуры данных."); }
        }
        throw new Error("Некорректный формат данных от ИИ.");
    }
};

const EXTRACTION_PROMPT = `
  ТЫ — ТЕХНИЧЕСКИЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
  ЗАДАЧА: Мгновенно разобрать текст на 10 новостей.
  СТИЛЬ: "МЫ".

  ВЕРНИ ТОЛЬКО JSON ПО ЭТОЙ СХЕМЕ:
  {
    "news": [{ "title": "Краткий заголовок", "summary": "Суть 2-3 предложения", "location": "Регион", "id": "id1" }],
    "formattedDigestText": "Общий текст выпуска для соцсетей (живой, с эмодзи)",
    "formattedShortDigest": "🚩 Заголовок — Едкий комментарий",
    "collagePrompt": "Описание картинки 16:9 для обложки"
  }
`;

export const processRawTextIntoDigest = async (rawText: string, globalSarcasm: number = 5): Promise<DigestData> => {
    const today = getCurrentDate();
    // Используем FLASH для скорости разбора
    const model = "gemini-3-flash-preview";

    const prompt = `
      РАЗБЕРИ ТЕКСТ ДЛЯ ВЫПУСКА ОТ ${today}. 
      Уровень иронии: ${globalSarcasm}/10. 
      ВЫДЕЛИ РОВНО 10 НОВОСТЕЙ (если текста мало, добей актуальными трендами).

      ТЕКСТ:
      ${rawText}
    `;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: { 
                systemInstruction: EXTRACTION_PROMPT, 
                responseMimeType: "application/json",
                temperature: 0.2 // Низкая температура для стабильности структуры
            }
        });

        const data = robustJSONParse(response.text || "");

        // Гарантируем наличие ID и структуры
        data.news = (data.news || []).slice(0, 10).map((n: any, i: number) => ({
            id: n.id || `raw-${i}-${Date.now()}`,
            title: n.title || 'Новость без названия',
            summary: n.summary || 'Нет описания',
            location: n.location || 'РФ'
        }));
        data.hacks = data.hacks || [];
        data.facts = data.facts || [];

        return data as DigestData;
    } catch (error) {
        console.error("Critical Parsing error:", error);
        throw new Error("ИИ не смог разобрать этот текст. Попробуйте вставить текст без лишнего мусора или проверьте соединение.");
    }
};

export const generateCreativeContent = async (newsItem: NewsItem, sarcasmLevel: number): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  // Для написания длинных статей оставляем мощную PRO модель
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". СТИЛЬ: "МЫ".
    ЗАДАЧА: Написать глубокую статью (от 2500 знаков) и посты.
    Уровень сарказма: ${sarcasmLevel}/10.
    ВЕРНИ JSON с полями: siteArticle (headline, content, hashtags), telegramPost (content), vkPost (content), imagePrompts (array), metaDescription.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Новость: ${newsItem.title}. Факты: ${newsItem.summary}. Сделай развернутый анализ.`,
      config: { systemInstruction, responseMimeType: "application/json" },
    });
    return { newsId: newsItem.id, ...robustJSONParse(response.text || "") };
  } catch (error) {
    throw new Error(`Ошибка генерации статьи для: ${newsItem.title}`);
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Cinematic wide 16:9 photography. ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) { return ""; }
};

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
      const img = await generateImage(p);
      if (img) images.push(img);
      await delay(500); // Уменьшенная задержка
  }
  while (images.length < 3) images.push("https://placehold.co/1600x900?text=Generation+Error");
  return images;
};

import React, { useState, useEffect } from 'react';
import { generateCreativeContent, generateImagesForPack, generateImage, processRawTextIntoDigest } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { NewsCard } from './components/NewsCard';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [sarcasmLevels, setSarcasmLevels] = useState<Record<string, number>>({});
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const [rawText, setRawText] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    telegramBotToken: '', telegramChatId: '', vkAccessToken: '', vkOwnerId: '', wpUrl: '', wpUsername: 'admin', wpAppPassword: '' 
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { setPubConfig(prev => ({ ...prev, ...JSON.parse(saved) })); } catch (e) {}
    }
  }, []);

  const handleProcessRawText = async () => {
    if (!rawText.trim() || rawText.length < 20) {
        alert("Текст слишком короткий для разбора.");
        return;
    }

    setAppState(AppState.PROCESSING_MANUAL);
    setStatusMessage("Сканируем входящий поток...");

    // Имитация этапов для спокойствия пользователя
    const phases = [
        "Выделяем инфоповоды...",
        "Анализируем цифры...",
        "Пишем бегущую строку...",
        "Готовим обложку выпуска..."
    ];

    let phaseIdx = 0;
    const interval = setInterval(() => {
        if (phaseIdx < phases.length) {
            setStatusMessage(phases[phaseIdx]);
            phaseIdx++;
        }
    }, 2500);

    try {
        const data = await processRawTextIntoDigest(rawText);
        clearInterval(interval);
        setDigest(data);
        setAppState(AppState.SELECTING);
        if (data.collagePrompt) {
            generateImage(data.collagePrompt).then(img => {
               if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
            });
        }
    } catch (e: any) {
        clearInterval(interval);
        setErrorMsg(e.message || "Ошибка соединения.");
        setAppState(AppState.ERROR);
    }
  };

  const toggleNewsSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) {
        const newLevels = { ...sarcasmLevels };
        delete newLevels[id];
        setSarcasmLevels(newLevels);
        return prev.filter(i => i !== id);
      }
      if (prev.length >= MAX_SELECTION) return prev;
      setSarcasmLevels(l => ({ ...l, [id]: 5 }));
      return [...prev, id];
    });
  };

  const updateSarcasm = (id: string, val: number) => {
    setSarcasmLevels(prev => ({ ...prev, [id]: val }));
  };

  const handleGenerateContent = async () => {
    if (selectedNewsIds.length === 0) return;
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < selectedItems.length; i++) {
      const item = selectedItems[i];
      const level = sarcasmLevels[item.id] || 5;

      setStatusMessage(`[${i+1}/${selectedItems.length}] Пишем статью: ${item.title.substring(0, 30)}...`);

      try {
        const content = await generateCreativeContent(item, level);
