                  <div className="lg:col-span-4 h-full sticky top-32"><DigestPostViewer digest={digest!} pubConfig={pubConfig} /></div>
                  <div className="lg:col-span-8 space-y-12 pb-20">{generatedResults.map((res) => (<ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />))}</div>
