import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const ZHVANETSKY_PROMPT = `
ТЫ — МИХАИЛ ЖВАНЕЦКИЙ. Твой стиль: тонкая сатира, парадоксальные выводы, одесский колорит, короткие емкие фразы. 
Ты пишешь обзоры на современные новости туризма. В тексте должна быть ирония над трудностями, ценами и самим процессом отдыха.
Статья должна быть глубокой (минимум 2500 знаков), разделена на логические блоки.
`;

const DIGEST_SYSTEM_PROMPT = `
ТЫ — ГЛАВНЫЙ РЕДАКТОР ТУРИСТИЧЕСКОГО АГЕНТСТВА. 
ЗАДАЧА: Найти и структурировать 10 самых свежих и проверенных новостей туризма для граждан РФ на сегодня.
ДЛЯ КАЖДОЙ НОВОСТИ:
1. Заголовок.
2. Суть ровно в 2 предложениях.
3. Фраза для бегущей строки (1 предложение + эмодзи в начале).

ВЕРНИ JSON:
{
  "news": [{ "id": "1", "title": "...", "summary": "...", "location": "...", "ticker": "🚩 ..." }],
  "formattedDigestText": "Общий связный текст дайджеста...",
  "formattedShortDigest": "Строка из всех ticker через пробелы",
  "collagePrompt": "Описание фотореалистичной обложки: travel concept, ultra-realistic, 8k"
}
`;

export const fetchRealNews = async (): Promise<DigestData> => {
  const today = getCurrentDate();
  const model = "gemini-3-flash-preview"; // Flash для скорости поиска

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди 10 актуальных новостей туризма для россиян на ${today}. Используй поиск. Проверь визы, новые рейсы, цены.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: DIGEST_SYSTEM_PROMPT,
        responseMimeType: "application/json"
      }
    });

    const text = response.text || "";
    // Чистка JSON от возможных артефактов
    const cleaned = text.replace(/```json/g, "").replace(/```/g, "").trim();
    return JSON.parse(cleaned);
  } catch (error) {
    console.error("Search error:", error);
    throw new Error("Не удалось собрать новости из сети. Проверьте соединение.");
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { 
        parts: [{ text: `Photorealistic, 8k, raw photo, high detail, travel photography, wide angle, cinematic lighting. ${prompt}` }] 
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) {
    console.warn("Image generation failed:", err);
    return "https://placehold.co/1600x900?text=Photo+Pending";
  }
};

export const generateArticleZhvanetsky = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview"; // Pro для сложного стиля

  const systemInstruction = `
    ${ZHVANETSKY_PROMPT}
    Верни JSON:
    {
      "siteArticle": { "headline": "Заголовок в стиле Жванецкого", "content": "Текст статьи (Markdown)", "hashtags": "теги" },
      "telegramPost": { "content": "Пост для ТГ" },
      "vkPost": { "content": "Пост для ВК" },
      "imagePrompts": ["описание фото 1", "описание фото 2", "описание фото 3"],
      "metaDescription": "Описание для SEO"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью по новости: ${newsItem.title}. Суть: ${newsItem.summary}. Стиль: Михаил Жванецкий.`,
      config: { systemInstruction, responseMimeType: "application/json" }
    });

    const data = JSON.parse(response.text.replace(/```json/g, "").replace(/```/g, "").trim());
    return { newsId: newsItem.id, ...data };
  } catch (error) {
    throw new Error(`Ошибка генерации статьи: ${newsItem.title}`);
  }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const results: string[] = [];
  for (const prompt of prompts.slice(0, 3)) {
    const img = await generateImage(prompt);
    results.push(img);
    // Небольшая задержка чтобы не спамить API
    await new Promise(r => setTimeout(r, 500));
  }
  return results;
};

import React, { useState, useEffect } from 'react';
import { fetchRealNews, generateArticleZhvanetsky, generateImage, generateImagesForArticle } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { NewsCard } from './components/NewsCard';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    telegramBotToken: '', telegramChatId: '', vkAccessToken: '', vkOwnerId: '', wpUrl: '', wpUsername: 'admin', wpAppPassword: '' 
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { setPubConfig(prev => ({ ...prev, ...JSON.parse(saved) })); } catch (e) {}
    }
  }, []);

  const handleStartProcess = async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Подключаемся к мировым лентам новостей...");
    setErrorMsg('');

    try {
      const data = await fetchRealNews();
      setDigest(data);
      setAppState(AppState.SELECTING);

      // Фоновая генерация обложки
      if (data.collagePrompt) {
          generateImage(data.collagePrompt).then(img => {
              if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
          });
      }
    } catch (e: any) {
      setErrorMsg(e.message || "Ошибка при сборе новостей.");
      setAppState(AppState.ERROR);
    }
  };

  const toggleNewsSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      if (prev.length >= MAX_SELECTION) return prev;
      return [...prev, id];
    });
  };

  const handleGenerateArticles = async () => {
    if (selectedNewsIds.length === 0) return;
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < selectedItems.length; i++) {
      const item = selectedItems[i];
      setStatusMessage(`[${i+1}/${selectedItems.length}] Входим в образ Жванецкого: ${item.title.substring(0, 30)}...`);

      try {
        const articlePack = await generateArticleZhvanetsky(item);
        setStatusMessage(`[${i+1}/${selectedItems.length}] Проявляем фотореалистичные кадры...`);
        const images = await generateImagesForArticle(articlePack.imagePrompts);

        setGeneratedResults(prev => [...prev, { ...articlePack, generatedImages: images }]);
      } catch (err: any) {
        console.error(err);
      }
    }
    setAppState(AppState.COMPLETED);
  };

  const todayDisplay = new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });

  return (
    <div className="min-h-screen bg-[#f8f9fa] pb-12">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />

      {/* Header */}
      <nav className="bg-brand-dark h-16 flex items-center px-6 sticky top-0 z-50 shadow-xl border-b border-brand-orange/30">
        <h1 className="text-white font-black uppercase tracking-tighter text-xl italic">
          TOUR<span className="text-brand-orange">GENIUS</span> AI
        </h1>
        <div className="ml-6 px-4 py-1 bg-brand-orange/10 border border-brand-orange/40 rounded-full text-[10px] text-brand-orange font-black uppercase tracking-widest animate-pulse">
           ВЫПУСК ОТ {todayDisplay}
        </div>
        <button onClick={() => setIsSettingsOpen(true)} className="ml-auto p-2 bg-white/5 rounded-full hover:bg-white/10 transition-all text-xl">⚙️</button>
      </nav>

      <main className="max-w-[1400px] mx-auto p-6">
        {appState === AppState.IDLE && (
          <div className="flex flex-col items-center py-32 bg-white rounded-[3rem] shadow-2xl border border-slate-100 animate-fade-in">
            <div className="w-24 h-24 bg-brand-orange/5 rounded-full flex items-center justify-center mb-8 ring-8 ring-brand-orange/5">
               <span className="text-6xl">🌍</span>
            </div>
            <h2 className="text-5xl font-black mb-6 uppercase text-brand-dark tracking-tighter italic text-center">Собрать свежий эфир</h2>
            <p className="text-slate-400 mb-12 max-w-lg text-center font-medium text-lg leading-relaxed">
              ИИ найдет 10 самых важных новостей туризма для россиян, подготовит дайджест и бегущую строку.
            </p>
            <button 
              onClick={handleStartProcess} 
              className="px-16 py-6 bg-brand-dark text-white font-black rounded-2xl uppercase tracking-[0.2em] hover:bg-brand-orange hover:scale-105 transition-all shadow-2xl shadow-brand-orange/20"
            >
              Начать поиск новостей
            </button>
          </div>
        )}

        {appState === AppState.SEARCHING && (
          <div className="flex flex-col items-center py-48 animate-fade-in">
            <div className="w-20 h-20 border-[6px] border-brand-orange border-t-transparent rounded-full animate-spin mb-10"></div>
            <h3 className="text-3xl font-black text-brand-dark tracking-tighter uppercase italic text-center animate-pulse">{statusMessage}</h3>
            <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-6">Редакция на связи с миром...</p>
