        {appState === AppState.SELECTING && digest && (
          <div className="animate-fade-in space-y-10">
            <div className="flex flex-col md:flex-row justify-between items-center bg-white/80 p-8 rounded-[2rem] border border-slate-200 backdrop-blur-xl sticky top-20 z-30 shadow-2xl gap-6">
               <div className="border-l-4 border-brand-orange pl-6">
                  <h2 className="text-2xl font-black uppercase text-brand-dark tracking-tighter italic">Эфир сформирован</h2>
                  <p className="text-xs font-black text-brand-orange uppercase tracking-widest mt-1">Выберите 2 темы для сатиры Жванецкого</p>
