                    {digest.news.map(n => (
                        <div key={n.id} onClick={() => toggleNewsSelection(n.id)} className={`cursor-pointer transition-all duration-300 group ${selectedNewsIds.includes(n.id) ? 'scale-[1.02]' : ''}`}>
                          <div className={`p-6 rounded-2xl border-2 h-full bg-white flex flex-col ${selectedNewsIds.includes(n.id) ? 'border-brand-orange shadow-2xl ring-4 ring-brand-orange/5' : 'border-slate-100 hover:border-brand-orange/30'}`}>
                              <div className="flex justify-between items-start mb-4">
                                  <span className="text-[10px] font-black uppercase bg-slate-100 px-2 py-1 rounded text-slate-500">{n.location || 'РФ'}</span>
                                  <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${selectedNewsIds.includes(n.id) ? 'bg-brand-orange border-brand-orange' : 'border-slate-200'}`}>
                                      {selectedNewsIds.includes(n.id) && <span className="text-white text-[10px]">✓</span>}
                                  </div>
                              </div>
                              <h4 className={`font-bold text-lg leading-tight mb-3 ${selectedNewsIds.includes(n.id) ? 'text-brand-orange' : 'text-brand-dark'}`}>{n.title}</h4>
                              <p className="text-slate-500 text-sm leading-relaxed mb-4 flex-grow">{n.summary}</p>
                              <div className="pt-4 border-t border-slate-50 text-[10px] font-mono text-slate-300 italic">
