            </div>
          </div>
        )}

        {(appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && (
           <div className="space-y-12 animate-fade-in">
              <div className="bg-brand-dark p-6 rounded-3xl flex justify-between items-center shadow-2xl border-b-4 border-brand-orange">
                  <h2 className="text-2xl font-black uppercase text-white tracking-tighter italic">
                    {appState === AppState.GENERATING_CONTENT ? statusMessage : 'Выпуск завершен. Михаил Михайлович доволен.'}
                  </h2>
                  <button onClick={() => window.location.reload()} className="px-6 py-2 bg-white/10 hover:bg-white/20 text-white rounded-xl text-[10px] font-black uppercase transition-all">Новый выпуск</button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  <div className="lg:col-span-4 h-full sticky top-32">
                    {digest && <DigestPostViewer digest={digest} pubConfig={pubConfig} />}
                  </div>
                  <div className="lg:col-span-8 space-y-12 pb-24">
                    {generatedResults.map((res) => (
                      <ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />
                    ))}
                    {appState === AppState.GENERATING_CONTENT && (
                      <div className="p-20 flex flex-col items-center justify-center bg-white rounded-[3rem] border-4 border-dashed border-slate-100">
                         <div className="w-12 h-12 border-4 border-brand-orange border-t-transparent rounded-full animate-spin mb-6"></div>
                         <p className="text-slate-400 font-black uppercase tracking-widest text-sm">Печатаем следующую статью...</p>
                      </div>
                    )}
                  </div>
              </div>
           </div>
        )}

        {appState === AppState.ERROR && (
           <div className="text-center py-24 bg-white rounded-[3rem] shadow-2xl animate-fade-in max-w-2xl mx-auto border-t-8 border-red-500">
              <div className="text-8xl mb-8">🛠️</div>
              <h2 className="text-3xl text-red-600 font-black mb-4 uppercase italic">Сбой в эфире</h2>
              <p className="text-slate-500 mb-10 px-12 text-lg font-medium">{errorMsg}</p>
              <button onClick={() => setAppState(AppState.IDLE)} className="bg-brand-dark text-white px-12 py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-brand-orange transition-all">Попробовать снова</button>
           </div>
        )}
      </main>
    </div>
  );
};

