import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Инициализация AI. Ключ берется из окружения.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

/**
 * Вспомогательная функция для чистки JSON ответов от разметки Markdown
 */
const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, "").replace(/```/g, "").replace(/\\n/g, " ").trim();
};

/**
 * Поиск и сбор 10 новостей туризма
 */
export const fetchRealNews = async (): Promise<DigestData> => {
  const today = getCurrentDate();
  const model = "gemini-3-flash-preview"; 

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР ТУРИСТИЧЕСКОГО АГЕНТСТВА. 
    ЗАДАЧА: Найти 10 самых свежих новостей туризма для граждан РФ (визы, рейсы, цены, курорты).

    ДЛЯ КАЖДОЙ НОВОСТИ:
    1. Заголовок (четкий).
    2. Пояснение (ровно 2 предложения).
    3. Фраза для бегущей строки (1 короткое предложение + тематический эмодзи в начале).

    ВЕРНИ ТОЛЬКО ЧИСТЫЙ JSON:
    {
      "news": [
        { "id": "uuid1", "title": "...", "summary": "...", "location": "...", "ticker": "✈️ ..." }
      ],
      "formattedDigestText": "Связный текст дайджеста для рассылки",
      "formattedShortDigest": "Все фразы из ticker через пробел",
      "collagePrompt": "Detailed photorealistic 8k prompt for a travel cover image"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди 10 актуальных новостей туризма для россиян на ${today}. Используй Google Search.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json"
      }
    });

    const cleaned = cleanJsonResponse(response.text || "");
    return JSON.parse(cleaned);
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Не удалось собрать новости. Попробуйте обновить страницу.");
  }
};

/**
 * Генерация фотореалистичных изображений
 */
export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { 
        parts: [{ text: `High-end professional photography, 8k resolution, cinematic lighting, shot on full-frame camera, extremely detailed, photorealistic travel scene: ${prompt}` }] 
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) {
    console.warn("Image generation failed", err);
    return "";
  }
};

/**
 * Генерация статьи в стиле Жванецкого
 */
export const generateArticleZhvanetsky = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — МИХАИЛ ЖВАНЕЦКИЙ. Твой стиль: Одесса, парадоксы, "тонкий прищур", ирония над бытом.
    ЗАДАЧА: Написать статью по новости туризма.
    ТРЕБОВАНИЯ:
    1. Текст от 2500 знаков. 
    2. Юмористический, саркастический взгляд на новость.
    3. Структура: Завязка, размышления о нашей жизни, парадоксальный финал.

    ВЕРНИ JSON:
    {
      "siteArticle": { "headline": "Заголовок в стиле Жванецкого", "content": "Текст статьи в Markdown", "hashtags": "теги" },
      "telegramPost": { "content": "Короткий едкий пост для ТГ" },
      "vkPost": { "content": "Пост для ВК с картинкой" },
      "imagePrompts": ["photorealistic wide shot of...", "hyper-realistic close up of...", "detailed travel scene..."],
      "metaDescription": "SEO описание"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Напиши гениально, как Жванецкий.`,
      config: { systemInstruction, responseMimeType: "application/json" }
    });

    const cleaned = cleanJsonResponse(response.text || "");
    const data = JSON.parse(cleaned);
    return { newsId: newsItem.id, ...data };
  } catch (error) {
    console.error("Article Generation Error:", error);
    throw new Error("Михаил Михайлович сегодня не в духе. Попробуйте позже.");
  }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 800)); // Задержка для стабильности
  }
  return images;
};

import React, { useState, useEffect } from 'react';
import { fetchRealNews, generateArticleZhvanetsky, generateImage, generateImagesForArticle } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    telegramBotToken: '', telegramChatId: '', vkAccessToken: '', vkOwnerId: '', wpUrl: '', wpUsername: 'admin', wpAppPassword: '' 
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { setPubConfig(prev => ({ ...prev, ...JSON.parse(saved) })); } catch (e) {}
    }
  }, []);

  const handleFetchNews = async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Сканируем мировые ленты через Google Search...");
    setErrorMsg('');

    try {
      const data = await fetchRealNews();
      setDigest(data);
      setAppState(AppState.SELECTING);

      // Фоновая обложка
      if (data.collagePrompt) {
          generateImage(data.collagePrompt).then(img => {
              if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
          });
      }
    } catch (e: any) {
      setErrorMsg(e.message || "Ошибка соединения.");
      setAppState(AppState.ERROR);
    }
  };

  const toggleSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      if (prev.length >= MAX_SELECTION) return prev;
      return [...prev, id];
    });
  };

  const handleGenerateLongreads = async () => {
    if (selectedNewsIds.length === 0) return;
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < selectedItems.length; i++) {
      const item = selectedItems[i];
      setStatusMessage(`[${i+1}/${selectedItems.length}] Пишем статью в стиле Жванецкого...`);

      try {
        const articlePack = await generateArticleZhvanetsky(item);
        setStatusMessage(`[${i+1}/${selectedItems.length}] Фотореалистичные кадры (3 шт)...`);
        const images = await generateImagesForArticle(articlePack.imagePrompts);
        setGeneratedResults(prev => [...prev, { ...articlePack, generatedImages: images }]);
      } catch (err: any) {
        console.error(err);
      }
    }
    setAppState(AppState.COMPLETED);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />

      {/* Ticker - Бегущая строка */}
      {digest && (
        <div className="bg-brand-dark overflow-hidden h-10 flex items-center border-b border-brand-orange/30">
          <div className="whitespace-nowrap animate-[marquee_60s_linear_infinite] flex items-center">
             <span className="text-brand-orange font-black text-xs uppercase tracking-widest px-10">БЕГУЩАЯ СТРОКА:</span>
             <span className="text-white font-medium text-sm">{digest.formattedShortDigest}</span>
             <span className="text-white font-medium text-sm ml-10">{digest.formattedShortDigest}</span>
          </div>
        </div>
      )}

      {/* Nav */}
      <nav className="bg-white h-16 flex items-center px-8 border-b border-slate-200 sticky top-0 z-50">
        <h1 className="text-brand-dark font-black tracking-tighter text-2xl italic">
          TOUR<span className="text-brand-orange">GENIUS</span> <span className="text-xs font-bold text-slate-300 not-italic ml-1">v3.0</span>
        </h1>
        <button onClick={() => setIsSettingsOpen(true)} className="ml-auto p-2 hover:bg-slate-100 rounded-full text-xl transition-all">⚙️</button>
      </nav>

      <main className="max-w-7xl mx-auto p-6 mt-4">
        {appState === AppState.IDLE && (
          <div className="bg-white rounded-[3rem] p-20 shadow-2xl border border-slate-100 text-center animate-fade-in mt-10">
            <div className="text-7xl mb-10 drop-shadow-lg">📡</div>
            <h2 className="text-5xl font-black text-brand-dark mb-6 uppercase tracking-tighter italic">Эфир Первого Туристического</h2>
            <p className="text-slate-400 text-xl max-w-2xl mx-auto mb-12 font-medium leading-relaxed">
              Мы найдем 10 реальных новостей для россиян, упакуем в дайджест и напишем статьи, которые Михаил Жванецкий прочитал бы с удовольствием.
            </p>
            <button 
              onClick={handleFetchNews} 
              className="bg-brand-dark text-white px-16 py-6 rounded-2xl font-black uppercase tracking-[0.2em] hover:bg-brand-orange hover:scale-105 transition-all shadow-2xl"
            >
              Запустить поиск
            </button>
          </div>
        )}

        {appState === AppState.SEARCHING && (
          <div className="flex flex-col items-center py-40 animate-fade-in">
             <div className="w-20 h-20 border-[6px] border-brand-orange border-t-transparent rounded-full animate-spin mb-10"></div>
             <h3 className="text-3xl font-black text-brand-dark uppercase italic tracking-tighter text-center animate-pulse">{statusMessage}</h3>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div className="animate-fade-in space-y-10">
            <div className="flex justify-between items-center bg-white p-8 rounded-3xl border border-slate-200 shadow-xl sticky top-20 z-40">
               <div>
                  <h2 className="text-2xl font-black text-brand-dark uppercase italic">Новости получены</h2>
                  <p className="text-xs font-bold text-brand-orange uppercase tracking-widest">Выберите 2 темы для больших статей Жванецкого</p>
               </div>
               <button 
                 onClick={handleGenerateLongreads}
                 disabled={selectedNewsIds.length === 0}
                 className={`px-12 py-4 rounded-xl font-black text-sm uppercase tracking-widest transition-all ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white shadow-lg scale-105' : 'bg-slate-100 text-slate-300'}`}
               >
                 Начать генерацию ({selectedNewsIds.length}/{MAX_SELECTION})
               </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4">
                  <DigestPostViewer digest={digest} pubConfig={pubConfig} />
                </div>
                <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-6 pb-20">
                   {digest.news.map(n => (
                      <div 
                        key={n.id} 
                        onClick={() => toggleSelection(n.id)}
                        className={`p-6 rounded-2xl border-2 transition-all cursor-pointer bg-white flex flex-col h-full group ${selectedNewsIds.includes(n.id) ? 'border-brand-orange shadow-2xl ring-4 ring-brand-orange/5 scale-[1.02]' : 'border-slate-100 hover:border-brand-orange/30'}`}
                      >
                         <div className="flex justify-between items-center mb-4">
                            <span className="text-[10px] font-black uppercase bg-slate-100 px-2 py-1 rounded text-slate-500">{n.location || 'АКТУАЛЬНО'}</span>
                            <div className={`w-5 h-5 rounded-full border-2 ${selectedNewsIds.includes(n.id) ? 'bg-brand-orange border-brand-orange' : 'border-slate-200'}`}></div>
                         </div>
                         <h4 className="font-bold text-lg mb-3 leading-tight text-brand-dark group-hover:text-brand-orange transition-colors">{n.title}</h4>
                         <p className="text-slate-500 text-sm leading-relaxed mb-4 flex-grow">{n.summary}</p>
                         <div className="text-[10px] font-mono text-slate-300 italic border-t pt-4">
                            {n.ticker}
                         </div>
                      </div>
                   ))}
                </div>
            </div>
          </div>
        )}

        {(appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && (
          <div className="space-y-12 animate-fade-in">
             <div className="bg-brand-dark p-8 rounded-3xl flex justify-between items-center shadow-2xl border-b-4 border-brand-orange">
                <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">
                   {appState === AppState.GENERATING_CONTENT ? statusMessage : 'Выпуск завершен. Читаем Жванецкого.'}
                </h2>
                <button onClick={() => window.location.reload()} className="bg-white/10 hover:bg-white/20 text-white px-6 py-2 rounded-xl text-[10px] font-black uppercase transition-all">В новый рейс</button>
             </div>

             <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4 h-full sticky top-32">
                  {digest && <DigestPostViewer digest={digest} pubConfig={pubConfig} />}
                </div>
                <div className="lg:col-span-8 space-y-12">
                   {generatedResults.map(res => (
                     <ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />
                   ))}
                   {appState === AppState.GENERATING_CONTENT && (
                     <div className="p-20 flex flex-col items-center justify-center bg-white rounded-[3rem] border-4 border-dashed border-slate-100 animate-pulse">
                        <div className="w-12 h-12 border-4 border-brand-orange border-t-transparent rounded-full animate-spin mb-6"></div>
                        <p className="text-slate-400 font-black uppercase text-xs">Михаил Михайлович пишет вторую страницу...</p>
                     </div>
                   )}
                </div>
             </div>
          </div>
        )}

        {appState === AppState.ERROR && (
          <div className="text-center py-24 bg-white rounded-[3rem] shadow-2xl max-w-2xl mx-auto border-t-8 border-red-500">
             <div className="text-8xl mb-8">📵</div>
             <h2 className="text-3xl font-black text-red-600 mb-4 uppercase italic">Сбой связи</h2>
             <p className="text-slate-500 text-lg mb-10 px-12">{errorMsg}</p>
             <button onClick={() => setAppState(AppState.IDLE)} className="bg-brand-dark text-white px-12 py-4 rounded-xl font-black uppercase shadow-xl hover:bg-brand-orange transition-all">Вернуться в порт</button>
          </div>
        )}
      </main>

      <style>{`
        @keyframes marquee {
          0% { transform: translateX(0); }
          100% { transform: translateX(-50%); }
        }
      `}</style>
    </div>
  );
};

export default App;
